import bisect

def table_zone_eval(zone, ops):
    # Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")
    initial, transitions = zone
    if not isinstance(initial, int):
        raise ValueError("Initial must be an integer")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Transitions must be a list/tuple")

    # Validate transitions
    T = []
    prev_t = None
    prev_off = initial
    for t, off in transitions:
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("Transition entries must be integers")
        if abs(t) > 10**13:
            raise ValueError("Transition time out of range")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if prev_t is not None and (t - prev_t) < 172800:
            raise ValueError("Transitions must be at least 172800 apart")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset changes too large")
        # Only add transitions that actually change the offset
        if off != prev_off:
            T.append((t, off))
        prev_t = t
        prev_off = off

    # Precompute W for bisect
    W = [t + off for t, off in T]

    # Helper function to resolve wall time to instant
    def resolve(w, fold):
        if not isinstance(w, int) or not isinstance(fold, int):
            raise ValueError("Invalid w or fold")
        if fold not in (0, 1):
            raise ValueError("Fold must be 0 or 1")
        if abs(w) > 10**13:
            raise ValueError("Wall time out of range")

        if not T:
            return w - initial

        # Find insertion point in W
        i = bisect.bisect_right(W, w)
        idx = i - 1

        if idx < 0:
            # Before first transition
            x = w - initial
            if x < T[0][0]:
                return x
            else:
                # In the first transition's gap
                a = initial
                b = T[0][1]
                T_val = T[0][0]
                if b > a:
                    if T_val + a <= w < T_val + b:
                        return w - a if fold == 0 else w - b
                else:
                    if T_val + b <= w < T_val + a:
                        return w - b if fold == 0 else w - a
                # This should not happen due to problem constraints
                return x
        elif idx >= len(T):
            # After last transition
            return w - T[-1][1]
        else:
            # Between transitions
            k = idx + 1  # current transition is T[k]
            a = T[idx][1] if idx >= 0 else initial
            b = T[k][1]
            T_val = T[k][0]
            # Check if in the gap of transition k
            if b > a:
                gap_start = T_val + a
                gap_end = T_val + b
                if gap_start <= w < gap_end:
                    return w - a if fold == 0 else w - b
            else:
                gap_start = T_val + b
                gap_end = T_val + a
                if gap_start <= w < gap_end:
                    return w - b if fold == 0 else w - a
            # In continuous region
            return w - a

    # Helper function to get wall time from instant
    def get_wall(x):
        if not isinstance(x, int):
            raise ValueError("Instant must be integer")
        if abs(x) > 10**13:
            raise ValueError("Instant out of range")

        if not T:
            return (x + initial, 0)

        # Find current offset
        i = bisect.bisect_right([t for t, _ in T], x)
        if i == 0:
            current_off = initial
            prev_off = initial
        else:
            current_off = T[i-1][1]
            if i == 1:
                prev_off = initial
            else:
                prev_off = T[i-2][1]

        w = x + current_off
        # Determine fold
        f = 1 if current_off < prev_off else 0
        return (w, f)

    # Process each operation
    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Operation must be a list/tuple")
        if len(op) < 2:
            raise ValueError("Operation too short")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Operation name must be string")
        if name not in ('instant', 'wall', 'add'):
            raise ValueError("Unknown operation")

        if name == 'instant':
            if len(op) != 3:
                raise ValueError("instant requires 3 elements")
            _, w, fold = op
            x = resolve(w, fold)
            results.append(x)
        elif name == 'wall':
            if len(op) != 2:
                raise ValueError("wall requires 2 elements")
            _, x = op
            w_f = get_wall(x)
            results.append(w_f)
        elif name == 'add':
            if len(op) != 5:
                raise ValueError("add requires 5 elements")
            _, w, fold, days, secs = op
            if not isinstance(days, int) or not isinstance(secs, int):
                raise ValueError("days and secs must be integers")
            if abs(days) > 10**6 or abs(secs) > 10**13:
                raise ValueError("Values out of range")
            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            w_f = get_wall(x2)
            results.append(w_f)

    return results

