def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone")
    initial, transitions = zone
    if not isinstance(initial, int):
        raise ValueError("Invalid initial")
    if abs(initial) > 50400:
        raise ValueError("Initial out of range")

    # Validate transitions
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Invalid transitions")
    prev_t = -float('inf')
    prev_off = initial
    T = []
    for t, off in transitions:
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("Invalid transition")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("Transition out of range")
        if t <= prev_t + 172800:
            raise ValueError("Transition time spacing")
        if abs(off - prev_off) > 86400:
            raise ValueError("Transition offset change")
        if off != prev_off:
            T.append((t, off))
            prev_off = off
        prev_t = t

    # Precompute W
    W = [t + off for t, off in T]

    # Validate ops
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Invalid operation")
        if len(op) < 2:
            raise ValueError("Invalid operation")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Invalid operation name")
        if name not in ("instant", "wall", "add"):
            raise ValueError("Unknown operation")
        if name == "instant":
            if len(op) != 3:
                raise ValueError("Invalid instant")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or not isinstance(fold, int) or fold not in (0, 1):
                raise ValueError("Invalid instant parameters")
            if abs(w) > 10**13:
                raise ValueError("W out of range")
        elif name == "wall":
            if len(op) != 2:
                raise ValueError("Invalid wall")
            x = op[1]
            if not isinstance(x, int):
                raise ValueError("Invalid wall parameter")
            if abs(x) > 10**13:
                raise ValueError("X out of range")
        elif name == "add":
            if len(op) != 5:
                raise ValueError("Invalid add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not all(isinstance(v, int) for v in (w, fold, days, secs)):
                raise ValueError("Invalid add parameters")
            if fold not in (0, 1) or abs(days) > 10**6:
                raise ValueError("Invalid add parameters")
            if abs(w) > 10**13 or abs(secs) > 10**13:
                raise ValueError("Add parameters out of range")

    def resolve(w, fold):
        if not T:
            return w - initial
        i = bisect.bisect_right(W, w)
        idx = i - 1
        if idx < 0:
            x = w - initial
            if x < T[0][0]:
                return x
            else:
                a = initial
                b = T[0][1]
                T_val = T[0][0]
                if b > a:
                    return w - a if fold == 0 else w - b
                else:
                    return w - a if fold == 0 else w - b
        elif idx >= len(T):
            return w - T[-1][1]
        else:
            k = idx
            a = T[k][1] if k > 0 else initial
            if k == 0:
                a = initial
            else:
                a = T[k-1][1]
            b = T[k][1]
            T_val = T[k][0]
            if b > a:
                gap_start = T_val + a
                gap_end = T_val + b
                if gap_start <= w < gap_end:
                    return w - a if fold == 0 else w - b
            else:
                fold_start = T_val + b
                fold_end = T_val + a
                if fold_start <= w < fold_end:
                    return w - a if fold == 0 else w - b
            return w - a

    def get_wall(x):
        if not T:
            return (x + initial, 0)
        i = bisect.bisect_left([t for t, _ in T], x)
        if i == 0:
            off = initial
            f = 0
        else:
            off = T[i-1][1]
            if i < len(T) and T[i-1][1] < T[i][1]:
                f = 0
            else:
                f = 1
        w = x + off
        if i < len(T):
            next_off = T[i][1]
            if off < next_off:
