    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Transitions must be a list or tuple")
    prev_t = None
    prev_off = initial
    T = []
    W = []
    for t, off in transitions:
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("Transition entries must be integers")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("Transition out of range")
        if prev_t is not None:
            if t - prev_t < 172800:
                raise ValueError("Transitions too close")
            if abs(off - prev_off) > 86400:
                raise ValueError("Offset change too large")
        # Filter out transitions with same offset as previous
        if off != prev_off:
            T.append((t, off))
            W.append(t + off)
            prev_off = off
        prev_t = t

    # Preprocess T and W
    T = tuple(T)
    W = tuple(W)

    def resolve(w, fold):
        # Validate w and fold
        if not isinstance(w, int) or abs(w) > 10**13:
            raise ValueError("Invalid w")
        if fold not in (0, 1):
            raise ValueError("Invalid fold")

        # Find insertion index
        i = bisect.bisect_right(W, w)
        idx = i - 1

        if idx < 0:
            # Before first transition
            x_candidate = w - initial
            if x_candidate < T[0][0]:
                return x_candidate
            else:
                # Check if in first transition's gap/overlap
                a = initial
                b = T[0][1]
                t_val = T[0][0]
                if b > a:
                    # Gap between t_val + a and t_val + b
                    if t_val + a <= w < t_val + b:
                        return w - a if fold == 0 else w - b
                else:
                    # Overlap between t_val + b and t_val + a
                    if t_val + b <= w < t_val + a:
                        return w - a if fold == 0 else w - b
                # Else, it's a valid instant (but this shouldn't happen)
                return x_candidate
        elif idx >= len(T):
            # After last transition
            return w - T[-1][1]
        else:
            # Between transitions
            k = idx + 1
            a = T[idx][1] if idx >=0 else initial
            b = T[k][1]
            t_val = T[k][0]

            # Check if in transition k's gap/overlap
            if b > a:
                # Gap between t_val + a and t_val + b
                if t_val + a <= w < t_val + b:
                    return w - a if fold == 0 else w - b
            else:
                # Overlap between t_val + b and t_val + a
                if t_val + b <= w < t_val + a:
                    return w - a if fold == 0 else w - b

            # Else, in continuous region
            # Find the offset before transition k
            if k == 0:
                prev_off = initial
            else:
                prev_off = T[k-1][1]
            return w - prev_off

    def get_wall(x, fold):
        # Find the applicable offset at x
        if not isinstance(x, int) or abs(x) > 10**13:
            raise ValueError("Invalid x")

        # Find the last transition with t <= x
        i = bisect.bisect_left([t for t, _ in T], x)
        if i == 0:
            offset = initial
        else:
            offset = T[i-1][1]

