def validate(n, s, leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be a list or tuple")
    if len(leaps) > 100:
        raise ValueError("leaps must have at most 100 entries")

    for leap in leaps:
        if not isinstance(leap, (list, tuple)) or len(leap) != 3:
            raise ValueError("each leap must be a list or tuple of 3 integers")
        y, m, delta = leap
        if not (isinstance(y, int) and not isinstance(y, bool)):
            raise ValueError("year must be an integer")
        if not (isinstance(m, int) and not isinstance(m, bool)):
            raise ValueError("month must be an integer")
        if not (isinstance(delta, int) and not isinstance(delta, bool)):
            raise ValueError("delta must be an integer")
        if not (1970 <= y <= 2400):
            raise ValueError("year must be between 1970 and 2400")
        if not (1 <= m <= 12):
            raise ValueError("month must be between 1 and 12")
        if delta not in (1, -1):
            raise ValueError("delta must be 1 or -1")

    # Check strictly increasing (year, month)
    prev_y, prev_m = -1, -1
    for y, m, _ in leaps:
        if (y, m) <= (prev_y, prev_m):
            raise ValueError("leaps must be in strictly increasing (year, month) order")
        prev_y, prev_m = y, m

    # Check (1970, 1) is not present
    if leaps and (leaps[0][0], leaps[0][1]) == (1970, 1):
        raise ValueError("leap (1970, 1) is not allowed")

    # Validate n and s
    if n is not None:
        if not isinstance(n, int) or isinstance(n, bool):
