def days_from_epoch(y, m, d):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)

    def days_in_month(month, leap):
        if month == 2:
            return 29 if leap else 28
        elif month in (4, 6, 9, 11):
            return 30
        else:
            return 31

    # Days from 1970 to y-1
    leap_upto_y_minus_1 = ( (y-1)//4 ) - ( (y-1)//100 ) + ( (y-1)//400 )
    leap_upto_1969 = ( 1969//4 ) - ( 1969//100 ) + ( 1969//400 )
    days = (y - 1970)*365 + (leap_upto_y_minus_1 - leap_upto_1969)

    # Add days from months in current year up to m-1
    leap = is_leap(y)
    for month in range(1, m):
        days += days_in_month(month, leap)
    days += d - 1
    return days

def compute_E(leaps):
    E_list = []
    cum_delta = 0
    for (Y, M, delta) in leaps:
        if M == 12:
            next_y = Y + 1
            next_m = 1
        else:
            next_y = Y
            next_m = M + 1
        Dk = days_from_epoch(next_y, next_m, 1)
        E_k = 86400000 * Dk + 1000 * cum_delta
        E_list.append( (E_k, delta) )
        cum_delta += delta
    return E_list

def smeared_ms(n, leaps):
    validate(n, None, leaps)
    E_list = compute_E(leaps)
    correction = 0
    for E_k, delta_k in E_list:
        start = E_k - 1000000
        g = (n - start) // 1000
        g = max(0, g)
        g = min(g, 1000)
        correction += delta_k * g
    return n - correction

def unsmeared_ms(s, leaps):
    validate(None, s, leaps)
    E_list = compute_E(leaps)
    low = 0
    high = 10**16 + 200000
    res = None
    while low <= high:
        mid = (low + high) // 2
        current = smeared_ms(mid, leaps)
        if current < s:
            low = mid + 1
        else:
            high = mid - 1
            res = mid
    if res is None or smeared_ms(res, leaps) != s:
        raise ValueError("No valid n found for the given s")
    return res

