import heapq

def petri_starts(places, transitions, until, limit):
    # Validate inputs
    if not isinstance(places, dict):
        raise ValueError("places must be a dict")
    for place, count in places.items():
        if not isinstance(place, str) or len(place) == 0:
            raise ValueError("place names must be non-empty strings")
        if not isinstance(count, int) or isinstance(count, bool):
            raise ValueError("place counts must be integers")
        if count < 0 or count > 10**6:
            raise ValueError("place counts must be 0..1e6")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list or tuple")
    if len(transitions) > 50:
        raise ValueError("too many transitions")

    if not isinstance(until, int) or isinstance(until, bool):
        raise ValueError("until must be integer")
    if until < 0 or until > 10**12:
        raise ValueError("until must be 0..1e12")

    if not isinstance(limit, int) or isinstance(limit, bool):
        raise ValueError("limit must be integer")
    if limit < 1 or limit > 2000:
        raise ValueError("limit must be 1..2000")

    seen_names = set()
    for idx, trans in enumerate(transitions):
        if not isinstance(trans, (tuple, list)) or len(trans) != 6:
            raise ValueError("transition must be 6 elements")
        name, inputs, outputs, duration, priority, servers = trans

        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("transition name must be non-empty string")
        if name in seen_names:
            raise ValueError("duplicate transition name")
        seen_names.add(name)

        if not isinstance(inputs, dict):
            raise ValueError("inputs must be a dict")
        if not inputs:
            raise ValueError("inputs must not be empty")
        if not isinstance(outputs, dict):
            raise ValueError("outputs must be a dict")

        for p in inputs.keys():
            if p not in places:
                raise ValueError(f"input place {p} not in places")
        for p in outputs.keys():
            if p not in places:
                raise ValueError(f"output place {p} not in places")

        for p, w in inputs.items():
            if not isinstance(w, int) or w < 1 or w > 1000:
                raise ValueError(f"input weight for {p} must be 1..1000")
        for p, w in outputs.items():
            if not isinstance(w, int) or w < 1 or w > 1000:
                raise ValueError(f"output weight for {p} must be 1..1000")

        if not isinstance(duration, int) or duration < 0 or duration > 10**12:
            raise ValueError("duration must be 0..1e12")
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be integer")
        if not isinstance(servers, int) or servers < 1 or servers > 10**6:
            raise ValueError("servers must be 1..1e6")

    transitions_list = list(transitions)
    active_counts = {trans[0]: 0 for trans in transitions_list}
    tokens = dict(places)
    events = []
    results = []

    time = 0
    while len(results) < limit:
        # Process completions at current time
        while events and events[0][0] == time:
            completion_time, idx = heapq.heappop(events)
            trans = transitions_list[idx]
            for p, w in trans[2].items():
                tokens[p] += w
            active_counts[trans[0]] -= 1

        # Process starts
        started = False
        while True:
            best_trans = None
            best_prio = float('inf')
            best_idx = float('inf')

            for idx, trans in enumerate(transitions_list):
                name = trans[0]
                inputs_dict = trans[1]
                current_count = active_counts[name]
                servers = trans[5]

                if current_count >= servers:
                    continue

                enabled = True
                for p, w in inputs_dict.items():
                    if tokens[p] < w:
                        enabled = False
                        break
                if not enabled:
                    continue

                if trans[4] < best_prio or (trans[4] == best_prio and idx < best_idx):
                    best_trans = trans
                    best_prio = trans[4]
                    best_idx = idx

            if best_trans is None:
                break

            started = True
            # Consume inputs
            for p, w in best_trans[1].items():
                tokens[p] -= w

            results.append((time, best_trans[0]))
            if len(results) == limit:
                return results

            duration = best_trans[3]
            if duration == 0:
                # Add outputs immediately
                for p, w in best_trans[2].items():
                    tokens[p] += w
            else:
                heapq.heappush(events, (time + duration, best_idx))
                active_counts[best_trans[0]] += 1

        if not started:
            if not events:
                break
            next_time = events[0][0]
            if next_time > until:
                break
            time = next_time
        else:
            # Continue processing at same time
            continue

    return results

