    if not isinstance(gates, (list, tuple)) or not isinstance(stimuli, (list, tuple)) or not isinstance(watch, (list, tuple)):
        raise ValueError("gates, stimuli, watch must be lists or tuples")
    if len(gates) > 60 or len(stimuli) > 200:
