    all_signals = set()
    for gate in gates:
        out, op, ins, delay = gate
        all_signals.add(out)
        for inp in ins:
            all_signals.add(inp)
    for t, sig, val in stimuli:
        all_signals.add(sig)
    for name in watch:
        all_signals.add(name)

    # Validate gates' structure and contents
    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    for gate in gates:
        if len(gate) != 4:
            raise ValueError("Each gate must be a 4-tuple")
        out, op, ins, delay = gate
        if not isinstance(out, str) or not out:
            raise ValueError("Gate output must be a non-empty string")
        if op not in valid_ops:
            raise ValueError(f"Invalid op: {op}")
        if not isinstance(ins, (list, tuple)) or any(not isinstance(s, str) or not s for s in ins):
            raise ValueError("Gate ins must be a list/tuple of non-empty strings")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} requires exactly 1 input")
        if op not in ("NOT", "BUF") and (len(ins) < 2 or len(ins) > 4):
            raise ValueError(f"{op} requires 2-4 inputs")
        if not isinstance(delay, int) or delay < 0 or delay > 10**12:
            raise ValueError("Gate delay must be an integer between 0 and 1e12")

    # Build edges for cycle detection
    edges = defaultdict(list)
    for gate in gates:
        out, op, ins, delay = gate
        for inp in ins:
            edges[inp].append(out)

    # Cycle detection using DFS
    def has_cycle():
        visited = set()
        rec_stack = set()
        def dfs(node):
            if node in rec_stack:
                return True
            if node in visited:
                return False
            visited.add(node)
            rec_stack.add(node)
            for neighbor in edges[node]:
                if dfs(neighbor):
                    return True
            rec_stack.remove(node)
            return False
        for node in all_signals:
            if node not in visited:
                if dfs(node):
                    return True
        return False

    if has_cycle():
        raise ValueError("Cycle detected in signal graph")

    # Identify primary inputs
    outputs_of_gates = set(gate[0] for gate in gates)
    primary_inputs = set()
    for gate in gates:
        for inp in gate[2]:
            if inp not in outputs_of_gates:
                primary_inputs.add(inp)

    # Validate stimuli signals are primary inputs
    for t, sig, val in stimuli:
        if sig not in primary_inputs:
            raise ValueError(f"Stimulus signal {sig} is not a primary input")
        if not isinstance(val, int) or val not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

    # Validate watch signals are known
    for name in watch:
        if name not in all_signals:
            raise ValueError(f"Watch name {name} is unknown")

    # Prepare data structures
    gates_by_out = {gate[0]: gate for gate in gates}
    values = {name: 0 for name in all_signals}
    pending = {}  # out -> (value, due_time)
    trace = {name: [] for name in watch}
    prev_value = {name: 0 for name in watch}

    # Collect initial event times
    event_heap = []
    seen_times = set()
    seen_times.add(0)
    for t, sig, val in stimuli:
        if t <= until:
            seen_times.add(t)
    for t in seen_times:
        heapq.heappush(event_heap, t)

