        to_apply = []
        # Process in rounds until no more assignments due at t
        while True:
            # Batch phase
            # First round: process stimuli
            if not to_apply:
                # First round: process stimuli
                for stim in stimuli:
                    stim_t, sig, val = stim
                    if stim_t == t:
                        old_val = values[sig]
                        values[sig] = val
                        if old_val != val:
                            changed_signals.add(sig)
                # Apply pending assignments due at t
                new_pending = {}
                applied = []
                for out_name in pending:
                    value, due = pending[out_name]
                    if due == t:
                        applied.append((out_name, value))
                    else:
                        new_pending[out_name] = (value, due)
                pending = new_pending
                # Apply the assignments
                for out_name, value in applied:
                    old_val = values[out_name]
                    values[out_name] = value
                    if old_val != value:
                        changed_signals.add(out_name)
                to_apply = applied.copy()
            else:
                # Subsequent rounds: process pending assignments due at t (delay 0)
                new_pending = {}
                applied = []
                for out_name in pending:
                    value, due = pending[out_name]
                    if due == t:
                        applied.append((out_name, value))
                    else:
                        new_pending[out_name] = (value, due)
                pending = new_pending
                # Apply the assignments
                for out_name, value in applied:
                    old_val = values[out_name]
                    values[out_name] = value
                    if old_val != value:
                        changed_signals.add(out_name)
                to_apply = applied.copy()

            # Evaluate phase
            # Determine gates to evaluate: those with inputs in changed_signals or all for t=0 first round
            gates_to_eval = []
            if t == 0 and not to_apply:
                # First round of t=0: evaluate all gates
                gates_to_eval = list(gates_by_out.values())
            else:
                # Find gates with any input in changed_signals
                for gate in gates_by_out.values():
                    out, op, ins, delay = gate
                    for inp in ins:
                        if inp in changed_signals:
                            gates_to_eval.append(gate)
                            break

            # Process each gate
            for gate in gates_to_eval:
                out, op, ins, delay = gate
                # Remove pending assignment for this gate's output if exists
                if out in pending:
                    del pending[out]
                # Compute new value
                input_values = [values[inp] for inp in ins]
                if op == "AND":
                    new_val = 1
                    for v in input_values:
                        new_val &= v
                elif op == "OR":
                    new_val = 0
                    for v in input_values:
                        new_val |= v
                elif op == "XOR":
                    new_val = input_values[0]
                    for v in input_values[1:]:
                        new_val ^= v
                elif op == "NAND":
                    new_val = 1
                    for v in input_values:
                        new_val &= v
                    new_val = 1 - new_val
                elif op == "NOR":
                    new_val = 0
                    for v in input_values:
                        new_val |= v
                    new_val = 1 - new_val
                elif op == "NOT":
                    new_val = 1 - input_values[0]
                elif op == "BUF":
                    new_val = input_values[0]
                else:
                    raise ValueError(f"Unexpected op {op}")

                current_val = values[out]
                if new_val != current_val:
                    due_time = t + delay
                    if due_time <= until:
                        pending[out] = (new_val, due_time)
                        if due_time not in seen_times:
                            heapq.heappush(event_heap, due_time)
                            seen_times.add(due_time)

            # Check if there are more pending assignments due at t
            has_more = any(due == t for (value, due) in pending.values())
            if not has_more:
                break

        # Update trace for watched signals
        for name in watch:
            current_val = values[name]
            if current_val != prev_value[name]:
                trace[name].append((t, current_val))
                prev_value[name] = current_val

    return trace

