from collections import defaultdict

def gate_trace(gates, stimuli, watch, until):
    # Validation Phase
    if not isinstance(gates, (list, tuple)) or not isinstance(stimuli, (list, tuple)):
        raise ValueError("gates and stimuli must be lists or tuples")
    if len(gates) > 60 or len(stimuli) > 200:
        raise ValueError("Too many gates or stimuli")
    if not isinstance(until, int) or until < 0 or until > 10**12:
        raise ValueError("until must be an integer between 0 and 1e12")

    # Collect all known signals and validate gates
    known_signals = set()
    gates_by_out = {}
    edges = defaultdict(list)  # input -> [outputs]
    for gate in gates:
        out, op, ins, delay = gate
        if not isinstance(out, str) or not out:
            raise ValueError("Invalid gate output name")
        if out in gates_by_out:
            raise ValueError("Duplicate gate output")
        if op not in {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}:
            raise ValueError("Invalid gate operation")
        if op in {"NOT", "BUF"} and len(ins) != 1:
            raise ValueError("NOT and BUF must have exactly one input")
        if op not in {"NOT", "BUF"} and not (2 <= len(ins) <= 4):
            raise ValueError("AND/OR/XOR/NAND/NOR must have 2-4 inputs")
        if delay < 0 or delay > 10**12:
            raise ValueError("Invalid gate delay")
        for inp in ins:
            if not isinstance(inp, str) or not inp:
                raise ValueError("Invalid input name")
            known_signals.add(inp)
            edges[inp].append(out)
        known_signals.add(out)
        gates_by_out[out] = (op, ins, delay)

    # Collect all signals from stimuli and watch
    stimuli_signals = set()
    watch_signals = set(watch)
    for time, signal, value in stimuli:
        if not isinstance(time, int) or time < 0 or time > 10**12:
            raise ValueError("Invalid stimulus time")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Invalid stimulus signal name")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")
        stimuli_signals.add(signal)
        known_signals.add(signal)
    for name in watch:
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid watch name")
        known_signals.add(name)

    # Validate stimuli signals are primary inputs (not outputs of any gate)
    outputs = set(gates_by_out.keys())
    for signal in stimuli_signals:
        if signal in outputs:
            raise ValueError("Stimulus signal is driven by a gate")

    # Validate watch names are known signals
    for name in watch:
        if name not in known_signals:
            raise ValueError("Unknown watch name")

    # Cycle detection using DFS
    def has_cycle():
        visited = set()
        rec_stack = set()

        def dfs(node):
            if node in rec_stack:
                return True
            if node in visited:
                return False
            visited.add(node)
            rec_stack.add(node)
            for neighbor in edges.get(node, []):
                if dfs(neighbor):
                    return True
            rec_stack.remove(node)
            return False

        for node in known_signals:
            if node not in visited:
                if dfs(node):
                    return True
        return False

    if has_cycle():
        raise ValueError("Cycle detected in signal graph")

    # Build stimuli dictionary
    stimuli_dict = defaultdict(list)
    for time, signal, value in stimuli:
        stimuli_dict[time].append((signal, value))

    # Initialize data structures
    values = {sig: 0 for sig in known_signals}
    pending = {}  # output -> (value, due_time)
    trace = {name: [] for name in watch_signals}
    prev_value = {name: 0 for name in watch_signals}

    # Collect initial event times (stimuli times)
    events = []
    seen_times = set()
    for t in stimuli_dict.keys():
        if t <= until:
            if t not in seen_times:
                heapq.heappush(events, t)
                seen_times.add(t)

    # Process events in order
    while events:
        t = heapq.heappop(events)
        if t > until:
            continue

        # Track changes in this round
        changed = set()

        # Round loop
        while True:
            # Batch phase
            if t == 0 or (t > 0 and not changed):
                # First round or initial round for t
                # Apply stimuli
                for signal, value in stimuli_dict.get(t, []):
                    if values[signal] != value:
                        changed.add(signal)
                        values[signal] = value
                # Apply pending assignments due at t
                to_process = []
                for out in list(pending.keys()):
                    if pending[out][1] == t:
                        to_process.append(out)
                for out in to_process:
                    val, due = pending.pop(out)
                    if values[out] != val:
                        changed.add(out)
                        values[out] = val
            else:
                # Subsequent rounds: apply pending assignments due at t (from delay 0)
                to_process = []
                for out in list(pending.keys()):
                    if pending[out][1] == t:
                        to_process.append(out)
                for out in to_process:
                    val, due = pending.pop(out)
                    if values[out] != val:
                        changed.add(out)
                        values[out] = val

            if not changed:
                break

            # Evaluate gates
            gates_to_eval = []
            if t == 0:
                gates_to_eval = list(gates_by_out.values())
            else:
                for gate_out in gates_by_out:
                    op, ins, delay = gates_by_out[gate_out]
                    for inp in ins:
                        if inp in changed:
                            gates_to_eval.append(gate_out)
                            break

            # Process gates to evaluate
            for out in gates_to_eval:
                op, ins, delay = gates_by_out[out]
                # Compute new value
                vals = [values[inp] for inp in ins]
                if op == "AND":
                    new_val = vals[0] & vals[1]
                elif op == "OR":
                    new_val = vals[0] | vals[1]
                elif op == "XOR":
                    new_val = vals[0] ^ vals[1]
                elif op == "NAND":
                    new_val = 1 - (vals[0] & vals[1])
                elif op == "NOR":
                    new_val = 1 - (vals[0] | vals[1])
                elif op == "NOT":
                    new_val = 1 - vals[0]
                elif op == "BUF":
                    new_val = vals[0]
                else:
                    new_val = 0  # Should not happen

                # Update pending assignment
                if out in pending:
                    del pending[out]
                if new_val != values[out]:
                    due_time = t + delay
                    if due_time <= until:
                        pending[out] = (new_val, due_time)
                        if due_time not in seen_times:
                            seen_times.add(due_time)
                            heapq.heappush(events, due_time)

            # Check if there are more assignments due at t
            has_more = False
            for out in pending:
                if pending[out][1] == t:
                    has_more = True
                    break
            if not has_more:
                break

        # Update trace for watched signals
        for name in watch_signals:
            if values[name] != prev_value[name]:
                trace[name].append((t, values[name]))
                prev_value[name] = values[name]

    return trace

