from typing import Dict, List, Tuple, Union

class Type:
    pass

class TVar(Type):
    def __init__(self, id: int):
        self.id = id

class Int(Type):
    pass

class Bool(Type):
    pass

class Str(Type):
    pass

class Unit(Type):
    pass

class List(Type):
    def __init__(self, elem: Type):
        self.elem = elem

class Ref(Type):
    def __init__(self, elem: Type):
        self.elem = elem

class Func(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

def apply(subst: Dict[int, Type], t: Type) -> Type:
    if isinstance(t, TVar):
        return subst.get(t.id, t)
    elif isinstance(t, List):
        return List(apply(subst, t.elem))
    elif isinstance(t, Ref):
        return Ref(apply(subst, t.elem))
    elif isinstance(t, Func):
        return Func(tuple(apply(subst, p) for p in t.params), apply(subst, t.ret))
    else:
        return t

def occurs_check(id: int, typ: Type, subst: Dict[int, Type]) -> bool:
    typ = apply(subst, typ)
    if isinstance(typ, TVar):
        return typ.id == id
    elif isinstance(typ, List):
        return occurs_check(id, typ.elem, subst)
    elif isinstance(typ, Ref):
        return occurs_check(id, typ.elem, subst)
    elif isinstance(typ, Func):
        for p in typ.params:
            if occurs_check(id, p, subst):
                return True
        return occurs_check(id, typ.ret, subst)
    else:
        return False

def unify(t1: Type, t2: Type, subst: Dict[int, Type]) -> None:
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if isinstance(t1, TVar):
        if t1.id == t2.id:
            return
        if occurs_check(t1.id, t2, subst):
            raise ValueError("Infinite type")
        subst[t1.id] = t2
    elif isinstance(t2, TVar):
        unify(t2, t1, subst)
    elif isinstance(t1, Int) and isinstance(t2, Int):
        return
    elif isinstance(t1, Bool) and isinstance(t2, Bool):
        return
    elif isinstance(t1, Str) and isinstance(t2, Str):
        return
    elif isinstance(t1, Unit) and isinstance(t2, Unit):
        return
    elif isinstance(t1, List) and isinstance(t2, List):
        unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        for p, q in zip(t1.params, t2.params):
            unify(p, q, subst)
        unify(t1.ret, t2.ret, subst)
    else:
        raise ValueError("Type mismatch")

def fresh_id() -> int:
    fresh_id.counter += 1
    return fresh_id.counter
fresh_id.counter = 0

def lookup(env: List[Dict[str, Type]], name: str) -> Type:
    for scope in env:
        if name in scope:
            return scope[name]
    raise ValueError(f"Unbound variable {name}")

def is_value(term: tuple) -> bool:
    if not isinstance(term, tuple):
        return False
    tag = term[0]
    if tag in {"int", "bool", "str", "unit", "var", "fn", "nil"}:
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    return False

def check_malformed(term: tuple) -> None:
    if not isinstance(term, tuple):
        raise ValueError("Term is not a tuple")
    if len(term) == 0:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag is not a string")
    allowed = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec",
               "nil", "cons", "match", "ref", "get", "set"}
    if tag not in allowed:
        raise ValueError(f"Unknown tag {tag}")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Invalid var")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Invalid fn")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or not params:
            raise ValueError("fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("fn params must be non-empty strings")
        if len(set(params)) != len(params):
            raise ValueError("fn params must be distinct")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Invalid call")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or not args:
            raise ValueError("call args must be non-empty tuple")
        check_malformed(f)
        for a in args:
            check_malformed(a)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Invalid let")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("let name must be non-empty string")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Invalid letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("letrec name must be non-empty string")
        if not (isinstance(e1, tuple) and e1 and e1[0] == "fn"):
            raise ValueError("letrec e1 must be fn")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Invalid nil")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Invalid cons")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Invalid match")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("match hn and tn must differ")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(hn)
        check_malformed(tn)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Invalid ref")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Invalid get")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Invalid set")
        check_malformed(term[1])
        check_malformed(term[2])

def free_vars(t: Type) -> set:
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, List):
        return free_vars(t.elem)
    elif isinstance(t, Ref):
        return free_vars(t.elem)
    elif isinstance(t, Func):
        s = set()
        for p in t.params:
            s.update(free_vars(p))
        s.update(free_vars(t.ret))
        return s
    else:
        return set()

def generalize(t: Type, env: List[Dict[str, Type]], subst: Dict[int, Type]) -> Type:
    t = apply(subst, t)
    env_vars = set()
    for scope in env:
        for typ in scope.values():
            env_vars.update(free_vars(typ))
    t_vars = free_vars(t)
    quantified = t_vars - env_vars
    if not quantified:
        return t
    # Replace quantified TVars with TVar instances that are now quantified
    # But for now, just return the type as is, since we can't represent quantified types
    # Wait, but in HM, the generalized type is a type scheme, but here we just return the type
    # and track the quantified variables as part of the substitution.
    # Wait, no. The generalize function here is supposed to return a type where the quantified variables are
    # universally quantified. But since we don't have a type scheme representation, we can't do that.
    # So the plan must be to just keep the type as is, and when it's used in a let, the variables are considered
    # bound by the let.
    return t

def infer(term: tuple, env: List[Dict[str, Type]], subst: Dict[int, Type]) -> Type:
    tag = term[0]
    if tag == "int":
        return Int()
    elif tag == "bool":
        return Bool()
    elif tag == "str":
        return Str()
    elif tag == "unit":
        return Unit()
    elif tag == "var":
        return lookup(env, term[1])
    elif tag == "fn":
        params, body = term[1], term[2]
        param_types = []
        new_scope = {}
        for name in params:
            tvar = TVar(fresh_id())
            new_scope[name] = tvar
            param_types.append(tvar)
        new_env = env + [new_scope]
        body_type = infer(body, new_env, subst)
        return Func(tuple(param_types), body_type)
    elif tag == "call":
        f, args = term[1], term[2]
        f_type = infer(f, env, subst)
        arg_types = [infer(a, env, subst) for a in args]
        if not isinstance(f_type, Func):
            raise ValueError("Not a function")
        if len(f_type.params) != len(arg_types):
            raise ValueError("Arity mismatch")
        for p, a in zip(f_type.params, arg_types):
            unify(p, a, subst)
        ret = apply(subst, f_type.ret)
        return ret
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(e1, env, subst)
        if is_value(e1):
            gen_type = generalize(e1_type, env, subst)
        else:
            gen_type = e1_type
        new_env = env + [{name: gen_type}]
        return infer(e2, new_env, subst)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        tvar = TVar(fresh_id())
        new_env = env + [{name: tvar}]
        e1_type = infer(e1, new_env, subst)
        unify(tvar, e1_type, subst)
        gen_type = generalize(e1_type, env, subst)
        new_env = env + [{name: gen_type}]
        return infer(e2, new_env, subst)
    elif tag == "nil":
        return List(TVar(fresh_id()))
    elif tag == "cons":
        h, t = term[1], term[2]
        h_type = infer(h, env, subst)
        t_type = infer(t, env, subst)
        elem_tvar = TVar(fresh_id())
        unify(t_type, List(elem_tvar), subst)
        unify(h_type, elem_tvar, subst)
        return List(elem_tvar)
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = infer(s, env, subst)
        a_tvar = TVar(fresh_id())
        unify(s_type, List(a_tvar), subst)
        new_env = env + [{hn: a_tvar, tn: List(a_tvar)}]
        e_nil_type = infer(e_nil, new_env, subst)
        e_cons_type = infer(e_cons, new_env, subst)
        unify(e_nil_type, e_cons_type, subst)
        return e_nil_type
    elif tag == "ref":
        e = term[1]
        e_type = infer(e, env, subst)
        return Ref(e_type)
    elif tag == "get":
        r = term[1]
        r_type = infer(r, env, subst)
        tvar = TVar(fresh_id())
        unify(r_type, Ref(tvar), subst)
        return tvar
    elif tag == "set":
        r, e = term[1], term[2]
        r_type = infer(r, env, subst)
        e_type = infer(e, env, subst)
        tvar = TVar(fresh_id())
        unify(r_type, Ref(tvar), subst)
        unify(e_type, tvar, subst)
        return Unit()

def format_type(t: Type, var_names: Dict[int, str] = None) -> str:
    if var_names is None:
        var_names = {}
    counter = [0]
    def get_name(id):
        if id not in var_names:
            var_names[id] = f"t{counter[0] + 1}"
            counter[0] += 1
        return var_names[id]
    def fmt(t):
        if isinstance(t, TVar):
            return get_name(t.id)
        elif isinstance(t, Int):
            return "Int"
        elif isinstance(t, Bool):
            return "Bool"
        elif isinstance(t, Str):
            return "Str"
        elif isinstance(t, Unit):
            return "Unit"
        elif isinstance(t, List):
            return f"List<{fmt(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{fmt(t.elem)}>"
        elif isinstance(t, Func):
            if len(t.params) == 1:
                p_str = fmt(t.params[0])
                return f"{p_str} -> {fmt(t.ret)}"
            else:
                params_str = ", ".join(fmt(p) for p in t.params)
                return f"({params_str}) -> {fmt(t.ret)}"
        else:
            raise ValueError(f"Unknown type {t}")
    return fmt(t)

def weak_infer(term: tuple) -> str:
    check_malformed(term)
    subst = {}
    env = []
    typ = infer(term, env, subst)
    typ = apply(subst, typ)
    var_names = {}
    result = format_type(typ, var_names)
    return result

from collections import defaultdict

class Type:
    pass

class TVar(Type):
    _id_counter = 0

    def __init__(self):
        self.id = TVar._id_counter
        TVar._id_counter += 1

    def __repr__(self):
        return f"t{self.id + 1}"

class Int(Type):
    def __repr__(self):
        return "Int"

class Bool(Type):
    def __repr__(self):
        return "Bool"

class Str(Type):
    def __repr__(self):
        return "Str"

class Unit(Type):
    def __repr__(self):
        return "Unit"

class ListT(Type):
    def __init__(self, elem):
        self.elem = elem

    def __repr__(self):
        return f"List<{self.elem}>"

class RefT(Type):
    def __init__(self, elem):
        self.elem = elem

    def __repr__(self):
        return f"Ref<{self.elem}>"

class FuncT(Type):
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret

    def __repr__(self):
        if len(self.params) == 1:
            p_str = f"({self.params[0]})" if isinstance(self.params[0], FuncT) else str(self.params[0])
            return f"{p_str} -> {self.ret}"
        else:
            return f"({', '.join(str(p) for p in self.params)}) -> {self.ret}"

def apply(subst, typ):
    if isinstance(typ, TVar):
        if typ.id in subst:
            return apply(subst, subst[typ.id])
        return typ
    elif isinstance(typ, ListT):
        return ListT(apply(subst, typ.elem))
    elif isinstance(typ, RefT):
        return RefT(apply(subst, typ.elem))
    elif isinstance(typ, FuncT):
        return FuncT(
            tuple(apply(subst, p) for p in typ.params),
            apply(subst, typ.ret)
        )
    return typ

def occurs(tvar, typ, subst):
    typ = apply(subst, typ)
    if isinstance(typ, TVar):
        return typ.id == tvar.id
    elif isinstance(typ, ListT):
        return occurs(tvar, typ.elem, subst)
    elif isinstance(typ, RefT):
        return occurs(tvar, typ.elem, subst)
    elif isinstance(typ, FuncT):
        for p in typ.params:
            if occurs(tvar, p, subst):
                return True
        return occurs(tvar, typ.ret, subst)
    return False

def unify(t1, t2, subst):
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if isinstance(t1, TVar) and isinstance(t2, TVar):
        if t1.id == t2.id:
            return subst
        subst = subst.copy()
        subst[t1.id] = t2
        return subst
    elif isinstance(t1, TVar):
        if occurs(t1, t2, subst):
            raise ValueError("Infinite type")
        subst = subst.copy()
        subst[t1.id] = t2
        return subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif isinstance(t1, Int) and isinstance(t2, Int):
        return subst
    elif isinstance(t1, Bool) and isinstance(t2, Bool):
        return subst
    elif isinstance(t1, Str) and isinstance(t2, Str):
        return subst
    elif isinstance(t1, Unit) and isinstance(t2, Unit):
        return subst
    elif isinstance(t1, ListT) and isinstance(t2, ListT):
        subst = unify(t1.elem, t2.elem, subst)
        return subst
    elif isinstance(t1, RefT) and isinstance(t2, RefT):
        subst = unify(t1.elem, t2.elem, subst)
        return subst
    elif isinstance(t1, FuncT) and isinstance(t2, FuncT):
        if len(t1.params) != len(t2.params):
            raise ValueError("Function arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            subst = unify(p1, p2, subst)
        subst = unify(t1.ret, t2.ret, subst)
        return subst
    else:
        raise ValueError("Type mismatch")

def check_malformed(term):
    if not isinstance(term, tuple):
        raise ValueError("Term is not a tuple")
    if len(term) == 0:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag is not a string")
    valid_tags = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in valid_tags:
        raise ValueError(f"Unknown tag: {tag}")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Invalid var term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("fn has wrong number of elements")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("fn params must be non-empty strings")
        if len(params) != len(set(params)):
            raise ValueError("fn params must be distinct")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("call has wrong number of elements")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        check_malformed(f)
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("let has wrong number of elements")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("let name must be non-empty string")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("letrec has wrong number of elements")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("letrec name must be non-empty string")
        if e1[0] != "fn":
            raise ValueError("letrec e1 must be a fn term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("nil has wrong number of elements")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("cons has wrong number of elements")
        h, t = term[1], term[2]
        check_malformed(h)
        check_malformed(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("match has wrong number of elements")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("match hn and tn must differ")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(hn)
        check_malformed(tn)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("ref has wrong number of elements")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("get has wrong number of elements")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("set has wrong number of elements")
        check_malformed(term[1])
        check_malformed(term[2])
    else:
        raise ValueError(f"Unknown tag: {tag}")

def initial_env():
    plus_type = FuncT((Int(), Int()), Int())
    a = TVar()
    eq_type = FuncT((a, a), Bool())
    size_type = FuncT((Str(),), Int())
    return [
        {
            "plus": plus_type,
            "eq": eq_type,
            "size": size_type
        }
    ]

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit"):
        return True
    elif tag == "var":
        return True
    elif tag == "fn":
        return True
    elif tag == "nil":
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    else:
        return False

def free_vars(typ, subst):
    typ = apply(subst, typ)
    if isinstance(typ, TVar):
        return {typ.id}
    elif isinstance(typ, ListT):
        return free_vars(typ.elem, subst)
    elif isinstance(typ, RefT):
        return free_vars(typ.elem, subst)
    elif isinstance(typ, FuncT):
        s = set()
        for p in typ.params:
            s.update(free_vars(p, subst))
        s.update(free_vars(typ.ret, subst))
        return s
    return set()

def generalize(typ, env, subst):
    typ = apply(subst, typ)
    env_vars = set()
    for env_dict in env:
        for t in env_dict.values():
            env_vars.update(free_vars(t, subst))
    fvs = free_vars(typ, subst)
    quantified = fvs - env_vars
    return typ  # In this implementation, generalization is not tracked explicitly but through TVar's scope

def infer(term, env, subst):
    tag = term[0]
    if tag == "int":
        return Int()
    elif tag == "bool":
        return Bool()
    elif tag == "str":
        return Str()
    elif tag == "unit":
        return Unit()
    elif tag == "var":
        name = term[1]
        for env_dict in reversed(env):
            if name in env_dict:
                return env_dict[name]
        raise ValueError(f"Unbound variable {name}")
    elif tag == "fn":
        params, body = term[1], term[2]
        param_types = [TVar() for _ in params]
        new_env = env.copy()
        new_env.insert(0, dict(zip(params, param_types)))
        body_type = infer(body, new_env, subst)
        return FuncT(tuple(param_types), body_type)
    elif tag == "call":
        f, args = term[1], term[2]
        f_type = infer(f, env, subst)
        arg_types = [infer(arg, env, subst) for arg in args]
        if not isinstance(f_type, FuncT):
            raise ValueError("Called term is not a function")
        for i in range(len(arg_types)):
            subst = unify(f_type.params[i], arg_types[i], subst)
        subst = unify(f_type.ret, arg_types[-1], subst)
        return apply(subst, f_type.ret)
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(e1, env, subst)
        if is_value(e1):
            e1_type = generalize(e1_type, env, subst)
        new_env = [dict(env[0])] + env  # Shadow previous bindings
        new_env[0][name] = e1_type
        return infer(e2, new_env, subst)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        if e1[0] != "fn":
            raise ValueError("letrec e1 must be a fn")
        rec_type = TVar()
        new_env = [dict(env[0])] + env
        new_env[0][name] = rec_type
        e1_type = infer(e1, new_env, subst)
        subst = unify(rec_type, e1_type, subst)
        e1_type = apply(subst, e1_type)
        e1_type = generalize(e1_type, env, subst)
        new_env[0][name] = e1_type
        return infer(e2, new_env, subst)
    elif tag == "nil":
        return ListT(TVar())
    elif tag == "cons":
        h, t = term[1], term[2]
        h_type = infer(h, env, subst)
        t_type = infer(t, env, subst)
        elem_type = TVar()
        subst = unify(t_type, ListT(elem_type), subst)
        subst = unify(h_type, elem_type, subst)
        return ListT(apply(subst, elem_type))
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = infer(s, env, subst)
        a_type = TVar()
        subst = unify(s_type, ListT(a_type), subst)
        new_env = env.copy()
        new_env.insert(0, {hn: a_type, tn: ListT(a_type)})
        e_nil_type = infer(e_nil, new_env, subst)
        e_cons_type = infer(e_cons, new_env, subst)
        subst = unify(e_nil_type, e_cons_type, subst)
        return apply(subst, e_nil_type)
    elif tag == "ref":
        e = term[1]
        e_type = infer(e, env, subst)
        return RefT(e_type)
    elif tag == "get":
        r = term[1]
        r_type = infer(r, env, subst)
        t = TVar()
        subst = unify(r_type, RefT(t), subst)
        return apply(subst, t)
    elif tag == "set":
        r, e = term[1], term[2]
        r_type = infer(r, env, subst)
        e_type = infer(e, env, subst)
        t = TVar()
        subst = unify(r_type, RefT(t), subst)
        subst = unify(e_type, t, subst)
        return Unit()
    else:
        raise ValueError(f"Unknown tag {tag}")

def weak_infer(term):
    check_malformed(term)
    TVar._id_counter = 0
    subst = {}
    env = initial_env()
    typ = infer(term, env, subst)
    final_typ = apply(subst, typ)
    return str(final_typ)

from typing import Dict, List, Tuple, Any, Callable, Set

class Type:
    def apply(self, subst: Dict[int, 'Type']) -> 'Type':
        raise NotImplementedError

    def free_vars(self) -> Set[int]:
        raise NotImplementedError

class TVar(Type):
    def __init__(self, id: int):
        self.id = id

    def apply(self, subst: Dict[int, Type]) -> Type:
        if self.id in subst:
            return subst[self.id].apply(subst)
        return self

    def free_vars(self) -> Set[int]:
        return {self.id}

    def __repr__(self):
        return f"TVar({self.id})"

class Int(Type):
    def apply(self, subst: Dict[int, Type]) -> Type:
        return self

    def free_vars(self) -> Set[int]:
        return set()

class Bool(Type):
    def apply(self, subst: Dict[int, Type]) -> Type:
        return self

    def free_vars(self) -> Set[int]:
        return set()

class Str(Type):
    def apply(self, subst: Dict[int, Type]) -> Type:
        return self

    def free_vars(self) -> Set[int]:
        return set()

class Unit(Type):
    def apply(self, subst: Dict[int, Type]) -> Type:
        return self

    def free_vars(self) -> Set[int]:
        return set()

class List(Type):
    def __init__(self, t: Type):
        self.t = t

    def apply(self, subst: Dict[int, Type]) -> Type:
        return List(self.t.apply(subst))

    def free_vars(self) -> Set[int]:
        return self.t.free_vars()

class Ref(Type):
    def __init__(self, t: Type):
        self.t = t

    def apply(self, subst: Dict[int, Type]) -> Type:
        return Ref(self.t.apply(subst))

    def free_vars(self) -> Set[int]:
        return self.t.free_vars()

class Func(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

    def apply(self, subst: Dict[int, Type]) -> Type:
        return Func(
            tuple(p.apply(subst) for p in self.params),
            self.ret.apply(subst)
        )

    def free_vars(self) -> Set[int]:
        return set().union(*[p.free_vars() for p in self.params], self.ret.free_vars())

def unify(t1: Type, t2: Type, subst: Dict[int, Type]) -> Dict[int, Type]:
    t1 = t1.apply(subst)
    t2 = t2.apply(subst)
    if isinstance(t1, TVar):
        if t1.id in subst:
            return unify(subst[t1.id], t2, subst)
        if t2.id == t1.id:
            return subst
        if t1.id in t2.free_vars():
            raise ValueError("Infinite type")
        new_subst = dict(subst)
        new_subst[t1.id] = t2
        return new_subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif type(t1) != type(t2):
        raise ValueError("Type mismatch")
    elif isinstance(t1, (Int, Bool, Str, Unit)):
        return subst
    elif isinstance(t1, List):
        return unify(t1.t, t2.t, subst)
    elif isinstance(t1, Ref):
        return unify(t1.t, t2.t, subst)
    elif isinstance(t1, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        new_subst = subst
        for p1, p2 in zip(t1.params, t2.params):
            new_subst = unify(p1, p2, new_subst)
        return unify(t1.ret, t2.ret, new_subst)
    else:
        raise ValueError("Unknown type")

def check_malformed(term: Any) -> None:
    if not isinstance(term, tuple):
        raise ValueError("Term is not a tuple")
    if len(term) == 0:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag is not a string")
    valid_tags = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in valid_tags:
        raise ValueError(f"Unknown tag {tag}")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Invalid var term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Invalid fn term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or len(p) == 0:
                raise ValueError("fn params must be non-empty strings")
        if len(params) != len(set(params)):
            raise ValueError("fn params must be distinct")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Invalid call term")
        f, args = term[1], term[2]
        check_malformed(f)
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Invalid let term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("let name must be non-empty string")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Invalid letrec term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("letrec name must be non-empty string")
        if not isinstance(e1, tuple) or e1[0] != "fn":
            raise ValueError("letrec e1 must be a fn term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Invalid nil term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Invalid cons term")
        h, t = term[1], term[2]
        check_malformed(h)
        check_malformed(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Invalid match term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not isinstance(tn, str) or hn == tn:
            raise ValueError("match hn and tn must be distinct strings")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Invalid ref term")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Invalid get term")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Invalid set term")
        check_malformed(term[1])
        check_malformed(term[2])
    for subterm in term[1:]:
        if isinstance(subterm, tuple):
            check_malformed(subterm)

def is_value(term: Any) -> bool:
    tag = term[0]
    if tag in {"int", "bool", "str", "unit", "var", "fn", "nil"}:
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    return False

def next_var() -> int:
    next_var.counter += 1
    return next_var.counter

next_var.counter = -1

def infer(term: Any, env: List[Dict[str, Type]], subst: Dict[int, Type]) -> Type:
    tag = term[0]
    if tag == "int":
        return Int()
    elif tag == "bool":
        return Bool()
    elif tag == "str":
        return Str()
    elif tag == "unit":
        return Unit()
    elif tag == "var":
        name = term[1]
        for e in env:
            if name in e:
                return e[name].apply(subst)
        raise ValueError(f"Unbound variable {name}")
    elif tag == "fn":
        params, body = term[1], term[2]
        param_bindings = {}
        for p in params:
            var_id = next_var()
            param_bindings[p] = TVar(var_id)
        new_env = [param_bindings] + env
        body_type = infer(body, new_env, subst)
        return Func(tuple(param_bindings[p] for p in params), body_type)
    elif tag == "call":
        f_term, args = term[1], term[2]
        f_type = infer(f_term, env, subst)
        args_types = [infer(arg, env, subst) for arg in args]
        ret_var = TVar(next_var())
        expected_type = Func(tuple(args_types), ret_var)
        subst = unify(f_type, expected_type, subst)
        return ret_var.apply(subst)
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(e1, env, subst)
        if is_value(e1):
            free = e1_type.free_vars()
            env_free = set()
            for e in env:
                env_free.update(t.free_vars() for t in e.values())
            env_free = set().union(*env_free) if env_free else set()
            quantified = free - env_free
            quantified_type = e1_type
            for var_id in quantified:
                quantified_type = TVar(var_id)
            new_env = [{name: quantified_type}] + env
            return infer(e2, new_env, subst)
        else:
            new_env = [{name: e1_type}] + env
            return infer(e2, new_env, subst)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(e1, env, subst)
        if not isinstance(e1_type, Func):
            raise ValueError("letrec e1 must be a function")
        env_rec = [{name: TVar(next_var())}] + env
        e1_type_rec = infer(e1, env_rec, subst)
        subst = unify(e1_type_rec, e1_type, subst)
        free = e1_type.free_vars()
        env_free = set()
        for e in env:
            env_free.update(t.free_vars() for t in e.values())
        env_free = set().union(*env_free) if env_free else set()
        quantified = free - env_free
        quantified_type = e1_type
        for var_id in quantified:
            quantified_type = TVar(var_id)
        new_env = [{name: quantified_type}] + env
        return infer(e2, new_env, subst)
    elif tag == "nil":
        return List(TVar(next_var()))
    elif tag == "cons":
        h, t = term[1], term[2]
        h_type = infer(h, env, subst)
        t_type = infer(t, env, subst)
        elem_var = TVar(next_var())
        subst = unify(t_type, List(elem_var), subst)
        subst = unify(h_type, elem_var, subst)
        return List(elem_var)
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = infer(s, env, subst)
        a_var = TVar(next_var())
        subst = unify(s_type, List(a_var), subst)
        new_env = [{hn: a_var, tn: List(a_var)}] + env
        e_nil_type = infer(e_nil, new_env, subst)
        e_cons_type = infer(e_cons, new_env, subst)
        subst = unify(e_nil_type, e_cons_type, subst)
        return e_nil_type.apply(subst)
    elif tag == "ref":
        e = term[1]
        e_type = infer(e, env, subst)
        return Ref(e_type)
    elif tag == "get":
        r = term[1]
        r_type = infer(r, env, subst)
        t_var = TVar(next_var())
        subst = unify(r_type, Ref(t_var), subst)
        return t_var
    elif tag == "set":
        r, e = term[1], term[2]
        r_type = infer(r, env, subst)
        e_type = infer(e, env, subst)
        t_var = TVar(next_var())
        subst = unify(r_type, Ref(t_var), subst)
        subst = unify(e_type, t_var, subst)
        return Unit()
    else:
        raise ValueError(f"Unknown tag {tag}")

def format_type(t: Type, var_order: List[int]) -> str:
    def get_name(tvar: TVar) -> str:
        return f"t{var_order.index(tvar.id) + 1}"

    def format(t: Type) -> str:
        if isinstance(t, TVar):
            return get_name(t)
        elif isinstance(t, Int):
            return "Int"
        elif isinstance(t, Bool):
            return "Bool"
        elif isinstance(t, Str):
            return "Str"
        elif isinstance(t, Unit):
            return "Unit"
        elif isinstance(t, List):
            return f"List<{format(t.t)}>"
        elif isinstance(t, Ref):
            return f"Ref<{format(t.t)}>"
        elif isinstance(t, Func):
            if len(t.params) == 1:
                p = format(t.params[0])
                if isinstance(t.params[0], Func):
                    p = f"({p})"
                return f"{p} -> {format(t.ret)}"
            else:
                parts = [format(p) for p in t.params]
                return f"({', '.join(parts)}) -> {format(t.ret)}"
        else:
            raise ValueError("Unknown type")

    var_order = []
    def collect_vars(t: Type):
        if isinstance(t, TVar):
            if t.id not in var_order:
                var_order.append(t.id)
        else:
            for child in [t] if isinstance(t, (List, Ref)) else [t.params, t.ret] if isinstance(t, Func) else []:
                if isinstance(child, list):
                    for c in child:
                        collect_vars(c)
                else:
                    collect_vars(child)
    collect_vars(t)
    return format(t)

def weak_infer(term: Any) -> str:
    check_malformed(term)
    subst = {}
    env = [
        {
            "plus": Func((Int(), Int()), Int()),
            "eq": Func((TVar(0), TVar(0)), Bool()),
            "size": Func((Str(),), Int())
        }
    ]
    inferred_type = infer(term, env, subst)
    final_type = inferred_type.apply(subst)
    return format_type(final_type, [])

from typing import Dict, List, Tuple, Any

class Type:
    pass

class TVar(Type):
    _id_counter = 0

    def __init__(self):
        self.id = TVar._id_counter
        TVar._id_counter += 1

    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id

    def __repr__(self):
        return f"t{self.id}"

class IntType(Type):
    def __repr__(self):
        return "Int"

class BoolType(Type):
    def __repr__(self):
        return "Bool"

class StrType(Type):
    def __repr__(self):
        return "Str"

class UnitType(Type):
    def __repr__(self):
        return "Unit"

class ListType(Type):
    def __init__(self, elem):
        self.elem = elem

    def __repr__(self):
        return f"List<{self.elem}>"

class RefType(Type):
    def __init__(self, elem):
        self.elem = elem

    def __repr__(self):
        return f"Ref<{self.elem}>"

class FuncType(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

    def __repr__(self):
        return f"({', '.join(map(str, self.params))}) -> {self.ret}"

def apply(s: Dict[int, Type], t: Type) -> Type:
    if isinstance(t, TVar):
        if t.id in s:
            return apply(s, s[t.id])
        else:
            return t
    elif isinstance(t, ListType):
        return ListType(apply(s, t.elem))
    elif isinstance(t, RefType):
        return RefType(apply(s, t.elem))
    elif isinstance(t, FuncType):
        new_params = tuple(apply(s, p) for p in t.params)
        new_ret = apply(s, t.ret)
        return FuncType(new_params, new_ret)
    else:
        return t

def occurs(var_id: int, t: Type) -> bool:
    if isinstance(t, TVar):
        return t.id == var_id
    elif isinstance(t, ListType):
        return occurs(var_id, t.elem)
    elif isinstance(t, RefType):
        return occurs(var_id, t.elem)
    elif isinstance(t, FuncType):
        for p in t.params:
            if occurs(var_id, p):
                return True
        return occurs(var_id, t.ret)
    else:
        return False

def unify(t1: Type, t2: Type, s: Dict[int, Type]) -> Dict[int, Type]:
    t1 = apply(s, t1)
    t2 = apply(s, t2)
    if t1 == t2:
        return s
    if isinstance(t1, TVar):
        if occurs(t1.id, t2):
            raise ValueError("Infinite type")
        new_s = dict(s)
        new_s[t1.id] = t2
        return new_s
    elif isinstance(t2, TVar):
        return unify(t2, t1, s)
    elif isinstance(t1, FuncType) and isinstance(t2, FuncType):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        new_s = s
        for p1, p2 in zip(t1.params, t2.params):
            new_s = unify(p1, p2, new_s)
        return unify(t1.ret, t2.ret, new_s)
    elif isinstance(t1, ListType) and isinstance(t2, ListType):
        return unify(t1.elem, t2.elem, new_s)
    elif isinstance(t1, RefType) and isinstance(t2, RefType):
        return unify(t1.elem, t2.elem, new_s)
    else:
        raise ValueError("Type mismatch")

def get_free_vars(t: Type) -> set:
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, ListType):
        return get_free_vars(t.elem)
    elif isinstance(t, RefType):
        return get_free_vars(t.elem)
    elif isinstance(t, FuncType):
        s = set()
        for p in t.params:
            s.update(get_free_vars(p))
        s.update(get_free_vars(t.ret))
        return s
    else:
        return set()

def generalize(t: Type, env: List[Dict[str, Type]], s: Dict[int, Type]) -> Type:
    free_in_env = set()
    for scope in env:
        for ty in scope.values():
            free_in_env.update(get_free_vars(apply(s, ty)))
    free_in_t = get_free_vars(apply(s, t))
    quantified = free_in_t - free_in_env
    return t  # This is a placeholder; actual quantification would need to bind variables

def is_value(term: Any) -> bool:
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    else:
        return False

def check_malformed(term: Any):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag not a string")
    allowed_tags = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in allowed_tags:
        raise ValueError("Unknown tag")
    if tag in ("int", "bool", "str", "unit", "var", "nil"):
        if len(term) != 2:
            raise ValueError(f"Wrong length for {tag}")
        if tag == "var" and not isinstance(term[1], str):
            raise ValueError("Var name not a string")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("fn has wrong length")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params not a non-empty tuple")
        for p in params:
            if not isinstance(p, str):
                raise ValueError("fn param not a string")
        if len(set(params)) != len(params):
            raise ValueError("fn params not distinct")
        check_malformed(term[2])
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("call has wrong length")
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        check_malformed(term[1])
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("let has wrong length")
        name = term[1]
        if not isinstance(name, str):
            raise ValueError("let name not a string")
        check_malformed(term[2])
        check_malformed(term[3])
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("letrec has wrong length")
        name = term[1]
        if not isinstance(name, str):
            raise ValueError("letrec name not a string")
        if term[2][0] != "fn":
            raise ValueError("letrec e1 must be fn")
        check_malformed(term[2])
        check_malformed(term[3])
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("cons has wrong length")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("match has wrong length")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("hn and tn must differ")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag in ("ref", "get", "set"):
        if len(term) != 3 and tag != "set":
            if tag == "ref":
                if len(term) != 2:
                    raise ValueError("ref has wrong length")
            elif tag == "get":
                if len(term) != 2:
                    raise ValueError("get has wrong length")
            else:
                raise ValueError(f"{tag} has wrong length")
        check_malformed(term[1])
        if tag == "set":
            check_malformed(term[2])
    else:
        raise ValueError("Unknown tag")

def initial_env():
    a = TVar()
    plus_type = FuncType((IntType(), IntType()), IntType())
    eq_type = FuncType((a, a), BoolType())
    size_type = FuncType((StrType(),), IntType())
    return [{"+": plus_type, "eq": eq_type, "size": size_type}]

def infer(term: Any, env: List[Dict[str, Type]], s: Dict[int, Type]) -> Tuple[Type, Dict[int, Type]]:
    tag = term[0]
    if tag == "int":
        return (IntType(), s)
    elif tag == "bool":
        return (BoolType(), s)
    elif tag == "str":
        return (StrType(), s)
    elif tag == "unit":
        return (UnitType(), s)
    elif tag == "var":
        name = term[1]
        for scope in env:
            if name in scope:
                var_type = scope[name]
                var_type = apply(s, var_type)
                return (var_type, s)
        raise ValueError("Unbound variable")
    elif tag == "fn":
        params = term[1]
        body = term[2]
        param_types = [TVar() for _ in params]
        new_env = [dict(zip(params, param_types))] + env
        body_type, s = infer(body, new_env, s)
        body_type = apply(s, body_type)
        return (FuncType(tuple(param_types), body_type), s)
    elif tag == "call":
        f_term = term[1]
        args_terms = term[2]
        f_type, s = infer(f_term, env, s)
        f_type = apply(s, f_type)
        if not isinstance(f_type, FuncType):
            raise ValueError("Call to non-function")
        arg_types = []
        for arg in args_terms:
            t, s = infer(arg, env, s)
            arg_types.append(apply(s, t))
        if len(f_type.params) != len(arg_types):
            raise ValueError("Arity mismatch")
        new_s = s
        for p, a in zip(f_type.params, arg_types):
            new_s = unify(p, a, new_s)
        ret_type = apply(new_s, f_type.ret)
        return (ret_type, new_s)
    elif tag == "let":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        e1_type, s = infer(e1, env, s)
        e1_type = apply(s, e1_type)
        if is_value(e1):
            gen_type = generalize(e1_type, env, s)
        else:
            gen_type = e1_type
        new_env = [{name: gen_type}] + env
        e2_type, s = infer(e2, new_env, s)
        return (e2_type, s)
    elif tag == "letrec":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        t_f = TVar()
        new_env = [{name: t_f}] + env
        e1_type, s = infer(e1, new_env, s)
        e1_type = apply(s, e1_type)
        s = unify(e1_type, t_f, s)
        e1_type = apply(s, e1_type)
        gen_type = generalize(e1_type, new_env, s)
        new_env = [{name: gen_type}] + env
        e2_type, s = infer(e2, new_env, s)
        return (e2_type, s)
    elif tag == "nil":
        return (ListType(TVar()), s)
    elif tag == "cons":
        h_term = term[1]
        t_term = term[2]
        h_type, s = infer(h_term, env, s)
        t_type, s = infer(t_term, env, s)
        elem = TVar()
        s = unify(t_type, ListType(elem), s)
        s = unify(h_type, elem, s)
        return (ListType(apply(s, elem)), s)
    elif tag == "match":
        s_term = term[1]
        e_nil = term[2]
        hn = term[3]
        tn = term[4]
        e_cons = term[5]
        s_type, s = infer(s_term, env, s)
        a = TVar()
        s = unify(s_type, ListType(a), s)
        new_env = [{hn: a, tn: ListType(a)}] + env
        e_nil_type, s = infer(e_nil, new_env, s)
        e_cons_type, s = infer(e_cons, new_env, s)
        s = unify(e_nil_type, e_cons_type, s)
        return (apply(s, e_nil_type), s)
    elif tag == "ref":
        e_term = term[1]
        e_type, s = infer(e_term, env, s)
        return (RefType(apply(s, e_type)), s)
    elif tag == "get":
        r_term = term[1]
        r_type, s = infer(r_term, env, s)
        t = TVar()
        s = unify(r_type, RefType(t), s)
        return (apply(s, t), s)
    elif tag == "set":
        r_term = term[1]
        e_term = term[2]
        r_type, s = infer(r_term, env, s)
        e_type, s = infer(e_term, env, s)
        t = TVar()
        s = unify(r_type, RefType(t), s)
        s = unify(e_type, t, s)
        return (UnitType(), s)
    else:
        raise ValueError("Unknown tag")

def format_type(t: Type) -> str:
    free_vars = []
    var_map = {}
    def collect(t):
        nonlocal free_vars, var_map
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_map[t.id] = len(free_vars)
                free_vars.append(t)
            return
        elif isinstance(t, ListType):
            collect(t.elem)
        elif isinstance(t, RefType):
            collect(t.elem)
        elif isinstance(t, FuncType):
            for p in t.params:
                collect(p)
            collect(t.ret)
    collect(t)
    var_to_str = {v.id: f"t{idx+1}" for idx, v in enumerate(free_vars)}
    def format(t):
        if isinstance(t, TVar):
            return var_to_str[t.id]
        elif isinstance(t, IntType):
            return "Int"
        elif isinstance(t, BoolType):
            return "Bool"
        elif isinstance(t, StrType):
            return "Str"
        elif isinstance(t, UnitType):
            return "Unit"
        elif isinstance(t, ListType):
            return f"List<{format(t.elem)}>"
        elif isinstance(t, RefType):
            return f"Ref<{format(t.elem)}>"
        elif isinstance(t, FuncType):
            if len(t.params) == 1:
                p_str = format(t.params[0])
                if isinstance(t.params[0], FuncType):
                    p_str = f"({p_str})"
                return f"{p_str} -> {format(t.ret)}"
            else:
                params_str = ", ".join(format(p) for p in t.params)
                return f"({params_str}) -> {format(t.ret)}"
    return format(t)

def weak_infer(term: Any) -> str:
    TVar._id_counter = 0
    check_malformed(term)
    env = initial_env()
    s = {}
    typ, s = infer(term, env, s)
    typ = apply(s, typ)
    return format_type(typ)

from typing import Dict, List, Tuple, Any

class Type:
    pass

class TVar(Type):
    def __init__(self, id: int):
        self.id = id
    def __repr__(self):
        return f"t{self.id}"
    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id
    def __hash__(self):
        return hash(self.id)

class Int(Type):
    def __repr__(self):
        return "Int"
    def __eq__(self, other):
        return isinstance(other, Int)

class Bool(Type):
    def __repr__(self):
        return "Bool"
    def __eq__(self, other):
        return isinstance(other, Bool)

class Str(Type):
    def __repr__(self):
        return "Str"
    def __eq__(self, other):
        return isinstance(other, Str)

class Unit(Type):
    def __repr__(self):
        return "Unit"
    def __eq__(self, other):
        return isinstance(other, Unit)

class List(Type):
    def __init__(self, elem: Type):
        self.elem = elem
    def __repr__(self):
        return f"List<{self.elem}>"
    def __eq__(self, other):
        return isinstance(other, List) and self.elem == other.elem

class Ref(Type):
    def __init__(self, elem: Type):
        self.elem = elem
    def __repr__(self):
        return f"Ref<{self.elem}>"
    def __eq__(self, other):
        return isinstance(other, Ref) and self.elem == other.elem

class Func(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret
    def __repr__(self):
        if len(self.params) == 1:
            p = self.params[0]
            if isinstance(p, Func):
                return f"({p}) -> {self.ret}"
            else:
                return f"{p} -> {self.ret}"
        else:
            return f"({', '.join(map(str, self.params))}) -> {self.ret}"
    def __eq__(self, other):
        return isinstance(other, Func) and self.params == other.params and self.ret == other.ret

def check_malformed(term: Any) -> None:
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag must be string")
    allowed_tags = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in allowed_tags:
        raise ValueError(f"Unknown tag {tag}")

    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Invalid var term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Invalid fn term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or len(p) == 0:
                raise ValueError("fn params must be non-empty strings")
        if len(set(params)) != len(params):
            raise ValueError("fn params must be distinct")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Invalid call term")
        f, args = term[1], term[2]
        check_malformed(f)
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Invalid let term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("let name must be non-empty string")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Invalid letrec term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("letrec name must be non-empty string")
        check_malformed(e1)
        check_malformed(e2)
        if e1[0] != "fn":
            raise ValueError("letrec e1 must be fn")
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Invalid nil term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Invalid cons term")
        h, t = term[1], term[2]
        check_malformed(h)
        check_malformed(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Invalid match term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("match hn and tn must differ")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(hn)
        check_malformed(tn)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Invalid ref term")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Invalid get term")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Invalid set term")
        check_malformed(term[1])
        check_malformed(term[2])

def free_vars(t: Type) -> set:
    if isinstance(t, TVar):
        return {t}
    elif isinstance(t, List):
        return free_vars(t.elem)
    elif isinstance(t, Ref):
        return free_vars(t.elem)
    elif isinstance(t, Func):
        s = set()
        for p in t.params:
            s.update(free_vars(p))
        s.update(free_vars(t.ret))
        return s
    else:
        return set()

def apply(subst: Dict[int, Type], t: Type) -> Type:
    if isinstance(t, TVar):
        if t.id in subst:
            return apply(subst, subst[t.id])
        else:
            return t
    elif isinstance(t, List):
        return List(apply(subst, t.elem))
    elif isinstance(t, Ref):
        return Ref(apply(subst, t.elem))
    elif isinstance(t, Func):
        return Func(tuple(apply(subst, p) for p in t.params), apply(subst, t.ret))
    else:
        return t

def occurs(tvar: TVar, t: Type) -> bool:
    if isinstance(t, TVar):
        return t.id == tvar.id
    elif isinstance(t, List):
        return occurs(tvar, t.elem)
    elif isinstance(t, Ref):
        return occurs(tvar, t.elem)
    elif isinstance(t, Func):
        for p in t.params:
            if occurs(tvar, p):
                return True
        return occurs(tvar, t.ret)
    else:
        return False

def unify(t1: Type, t2: Type, subst: Dict[int, Type]) -> Dict[int, Type]:
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if isinstance(t1, TVar):
        if t1 == t2:
            return subst
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        subst = dict(subst)
        subst[t1.id] = t2
        return subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif isinstance(t1, Int) and isinstance(t2, Int):
        return subst
    elif isinstance(t1, Bool) and isinstance(t2, Bool):
        return subst
    elif isinstance(t1, Str) and isinstance(t2, Str):
        return subst
    elif isinstance(t1, Unit) and isinstance(t2, Unit):
        return subst
    elif isinstance(t1, List) and isinstance(t2, List):
        return unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        return unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        subst = unify(t1.ret, t2.ret, subst)
        for p1, p2 in zip(t1.params, t2.params):
            subst = unify(p1, p2, subst)
        return subst
    else:
        raise ValueError("Type mismatch")

def is_value(term: Any) -> bool:
    tag = term[0]
    if tag in {"int", "bool", "str", "unit", "var", "fn", "nil"}:
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    else:
        return False

def weak_infer(term: Any) -> str:
    check_malformed(term)

    class Context:
        def __init__(self):
            self.subst = {}
            self.var_counter = 0
        def fresh(self) -> TVar:
            self.var_counter += 1
            return TVar(self.var_counter)

    ctx = Context()
    env: List[Dict[str, Type]] = []

    def infer(term: Any) -> Type:
        tag = term[0]
        if tag == "int":
            return Int()
        elif tag == "bool":
            return Bool()
        elif tag == "str":
            return Str()
        elif tag == "unit":
            return Unit()
        elif tag == "var":
            name = term[1]
            for scope in reversed(env):
                if name in scope:
                    return apply(ctx.subst, scope[name])
            raise ValueError(f"Unbound variable {name}")
        elif tag == "fn":
            params, body = term[1], term[2]
            param_types = []
            new_env = list(env)
            for p in params:
                tvar = ctx.fresh()
                param_types.append(tvar)
                new_env.append({p: tvar})
            body_type = infer(body)
            return Func(tuple(param_types), body_type)
        elif tag == "call":
            f_term, args = term[1], term[2]
            f_type = infer(f_term)
            arg_types = [infer(arg) for arg in args]
            ret_type = ctx.fresh()
            func_type = Func(tuple(arg_types), ret_type)
            ctx.subst = unify(f_type, func_type, ctx.subst)
            return apply(ctx.subst, ret_type)
        elif tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            e1_type = infer(e1)
            e1_type = apply(ctx.subst, e1_type)
            if is_value(e1):
                env_free = set()
                for s in env:
                    for t in s.values():
                        env_free.update(free_vars(apply(ctx.subst, t)))
                e1_free = free_vars(e1_type)
                quantified = e1_free - env_free
                generalized = e1_type
            else:
                generalized = e1_type
            env.append({name: generalized})
            e2_type = infer(e2)
            env.pop()
            return e2_type
        elif tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            e1_type_var = ctx.fresh()
            env.append({name: e1_type_var})
            e1_type = infer(e1)
            e1_type = apply(ctx.subst, e1_type)
            ctx.subst = unify(e1_type, e1_type_var, ctx.subst)
            e1_type = apply(ctx.subst, e1_type_var)
            env_free = set()
            for s in env:
                for t in s.values():
                    env_free.update(free_vars(apply(ctx.subst, t)))
            e1_free = free_vars(e1_type)
            quantified = e1_free - env_free
            generalized = e1_type
            env.pop()
            env.append({name: generalized})
            e2_type = infer(e2)
            env.pop()
            return e2_type
        elif tag == "nil":
            return List(ctx.fresh())
        elif tag == "cons":
            h, t = term[1], term[2]
            h_type = infer(h)
            t_type = infer(t)
            elem_type = ctx.fresh()
            ctx.subst = unify(t_type, List(elem_type), ctx.subst)
            ctx.subst = unify(h_type, elem_type, ctx.subst)
            return apply(ctx.subst, List(elem_type))
        elif tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            s_type = infer(s)
            a = ctx.fresh()
            ctx.subst = unify(s_type, List(a), ctx.subst)
            new_env = list(env)
            new_env.append({hn: a})
            new_env.append({tn: List(a)})
            e_nil_type = infer(e_nil)
            e_nil_type = apply(ctx.subst, e_nil_type)
            e_cons_type = infer(e_cons)
            e_cons_type = apply(ctx.subst, e_cons_type)
            ctx.subst = unify(e_nil_type, e_cons_type, ctx.subst)
            return apply(ctx.subst, e_nil_type)
        elif tag == "ref":
            e = term[1]
            e_type = infer(e)
            return Ref(e_type)
        elif tag == "get":
            r = term[1]
            r_type = infer(r)
            t = ctx.fresh()
            ctx.subst = unify(r_type, Ref(t), ctx.subst)
            return apply(ctx.subst, t)
        elif tag == "set":
            r, e = term[1], term[2]
            r_type = infer(r)
            e_type = infer(e)
            t = ctx.fresh()
            ctx.subst = unify(r_type, Ref(t), ctx.subst)
            ctx.subst = unify(e_type, t, ctx.subst)
            return Unit()
        else:
            raise ValueError("Unknown tag")

    result_type = infer(term)
    result_type = apply(ctx.subst, result_type)

    var_map = {}
    var_counter = 1

    def get_name(t: Type) -> str:
        nonlocal var_counter
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_map[t.id] = f"t{var_counter}"
                var_counter += 1
            return var_map[t.id]
        elif isinstance(t, List):
            return f"List<{get_name(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{get_name(t.elem)}>"
        elif isinstance(t, Func):
            if len(t.params) == 1:
                p = t.params[0]
                if isinstance(p, Func):
                    return f"({get_name(p)}) -> {get_name(t.ret)}"
                else:
                    return f"{get_name(p)} -> {get_name(t.ret)}"
            else:
                return f"({', '.join(get_name(p) for p in t.params)}) -> {get_name(t.ret)}"
        else:
            return repr(t)

    return get_name(result_type)

from typing import Dict, List, Tuple, Set, Any, Union, Optional
import sys

class Type:
    def __init__(self):
        pass

    def __repr__(self):
        return self.__str__()

class TVar(Type):
    def __init__(self, id: int):
        self.id = id

    def __str__(self):
        return f"t{self.id}"

class Int(Type):
    def __str__(self):
        return "Int"

class Bool(Type):
    def __str__(self):
        return "Bool"

class Str(Type):
    def __str__(self):
        return "Str"

class Unit(Type):
    def __str__(self):
        return "Unit"

class List(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __str__(self):
        return f"List<{self.elem}>"

class Ref(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __str__(self):
        return f"Ref<{self.elem}>"

class Func(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

    def __str__(self):
        if len(self.params) == 1:
            p_str = str(self.params[0])
            if isinstance(self.params[0], Func):
                p_str = f"({p_str})"
            return f"{p_str} -> {self.ret}"
        else:
            params_str = ", ".join(str(p) for p in self.params)
            return f"({params_str}) -> {self.ret}"

class TVar:
    _id_counter = 0

    @classmethod
    def fresh(cls):
        cls._id_counter += 1
        return cls(cls._id_counter - 1)

    def __init__(self, id: int):
        self.id = id

    def __repr__(self):
        return f"t{self.id}"

def free_vars(t: Type) -> Set[int]:
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, Func):
        s = set()
        for p in t.params:
            s.update(free_vars(p))
        s.update(free_vars(t.ret))
        return s
    elif isinstance(t, List):
        return free_vars(t.elem)
    elif isinstance(t, Ref):
        return free_vars(t.elem)
    else:
        return set()

def free_vars_in_env(env: List[Dict[str, Type]]) -> Set[int]:
    s = set()
    for scope in env:
        for typ in scope.values():
            s.update(free_vars(typ))
    return s

def apply(subst: Dict[int, Type], t: Type) -> Type:
    if isinstance(t, TVar):
        if t.id in subst:
            return apply(subst, subst[t.id])
        return t
    elif isinstance(t, Func):
        new_params = tuple(apply(subst, p) for p in t.params)
        new_ret = apply(subst, t.ret)
        return Func(new_params, new_ret)
    elif isinstance(t, List):
        return List(apply(subst, t.elem))
    elif isinstance(t, Ref):
        return Ref(apply(subst, t.elem))
    else:
        return t

def unify(t1: Type, t2: Type, subst: Dict[int, Type]) -> Dict[int, Type]:
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if isinstance(t1, TVar):
        if isinstance(t2, TVar):
            if t1.id == t2.id:
                return subst
            else:
                subst = dict(subst)
                subst[t1.id] = t2
                return subst
        else:
            # occurs check
            if t1.id in free_vars(t2):
                raise ValueError("Infinite type")
            subst = dict(subst)
            subst[t1.id] = t2
            return subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        new_subst = subst
        for p1, p2 in zip(t1.params, t2.params):
            new_subst = unify(p1, p2, new_subst)
        return unify(t1.ret, t2.ret, new_subst)
    elif isinstance(t1, List) and isinstance(t2, List):
        return unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        return unify(t1.elem, t2.elem, subst)
    elif type(t1) == type(t2):
        return subst
    else:
        raise ValueError("Type mismatch")

def check_malformed(term: Any) -> None:
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Malformed term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Malformed term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Malformed term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed term")
        for name in params:
            if not isinstance(name, str) or len(name) == 0:
                raise ValueError("Malformed term")
        if len(set(params)) != len(params):
            raise ValueError("Malformed term")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed term")
        check_malformed(f)
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("Malformed term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("Malformed term")
        if not (isinstance(e1, tuple) and e1[0] == "fn"):
            raise ValueError("Malformed term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed term")
        h, t = term[1], term[2]
        check_malformed(h)
        check_malformed(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Malformed term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("Malformed term")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed term")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed term")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed term")
        check_malformed(term[1])
        check_malformed(term[2])
    else:
        raise ValueError("Malformed term")

def is_value(term: Any) -> bool:
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    else:
        return False

def infer(term: Any, env: List[Dict[str, Type]], subst: Dict[int, Type]) -> Tuple[Type, Dict[int, Type]]:
    if isinstance(term, tuple) and len(term) > 0:
        tag = term[0]
        if tag == "int":
            return Int(), subst
        elif tag == "bool":
            return Bool(), subst
        elif tag == "str":
            return Str(), subst
        elif tag == "unit":
            return Unit(), subst
        elif tag == "var":
            name = term[1]
            for scope in env:
                if name in scope:
                    typ = apply(subst, scope[name])
                    return typ, subst
            raise ValueError("Unbound variable")
        elif tag == "fn":
            params, body = term[1], term[2]
            param_types = [TVar.fresh() for _ in params]
            new_scope = {name: typ for name, typ in zip(params, param_types)}
            new_env = [new_scope] + env
            body_type, subst = infer(body, new_env, subst)
            return Func(tuple(param_types), body_type), subst
        elif tag == "call":
            f, args = term[1], term[2]
            f_type, subst = infer(f, env, subst)
            if not isinstance(f_type, Func):
                raise ValueError("Call to non-function")
            arg_types = []
            for arg in args:
                typ, subst = infer(arg, env, subst)
                arg_types.append(typ)
            if len(f_type.params) != len(arg_types):
                raise ValueError("Arity mismatch")
            for p, a in zip(f_type.params, arg_types):
                subst = unify(p, a, subst)
            ret = apply(subst, f_type.ret)
            return ret, subst
        elif tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            e1_type, subst = infer(e1, env, subst)
            if is_value(term[2]):
                env_vars = free_vars_in_env(env)
                type_vars = free_vars(e1_type)
                quantified = type_vars - env_vars
                generalized = e1_type
            else:
                generalized = e1_type
            new_scope = {name: generalized}
            new_env = [new_scope] + env
            e2_type, subst = infer(e2, new_env, subst)
            return e2_type, subst
        elif tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            if not (isinstance(e1, tuple) and e1[0] == "fn"):
                raise ValueError("letrec requires e1 to be a function")
            T_f = TVar.fresh()
            new_scope = {name: T_f}
            new_env = [new_scope] + env
            e1_type, subst = infer(e1, new_env, subst)
            e1_type = apply(subst, e1_type)
            if not isinstance(e1_type, Func):
                raise ValueError("letrec e1 must be a function")
            env_vars = free_vars_in_env(env)
            type_vars = free_vars(e1_type)
            quantified = type_vars - env_vars
            generalized = e1_type
            new_scope = {name: generalized}
            new_env = [new_scope] + env
            e2_type, subst = infer(e2, new_env, subst)
            return e2_type, subst
        elif tag == "nil":
            return List(TVar.fresh()), subst
        elif tag == "cons":
            h, t = term[1], term[2]
            h_type, subst = infer(h, env, subst)
            t_type, subst = infer(t, env, subst)
            elem_var = TVar.fresh()
            subst = unify(t_type, List(elem_var), subst)
            subst = unify(h_type, elem_var, subst)
            return List(elem_var), subst
        elif tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            s_type, subst = infer(s, env, subst)
            A = TVar.fresh()
            subst = unify(s_type, List(A), subst)
            new_scope = {hn: A, tn: List(A)}
            new_env = [new_scope] + env
            e_nil_type, subst = infer(e_nil, new_env, subst)
            e_cons_type, subst = infer(e_cons, new_env, subst)
            subst = unify(e_nil_type, e_cons_type, subst)
            result_type = apply(subst, e_nil_type)
            return result_type, subst
        elif tag == "ref":
            e = term[1]
            e_type, subst = infer(e, env, subst)
            return Ref(e_type), subst
        elif tag == "get":
            r = term[1]
            r_type, subst = infer(r, env, subst)
            T = TVar.fresh()
            subst = unify(r_type, Ref(T), subst)
            return T, subst
        elif tag == "set":
            r, e = term[1], term[2]
            r_type, subst = infer(r, env, subst)
            e_type, subst = infer(e, env, subst)
            T = TVar.fresh()
            subst = unify(r_type, Ref(T), subst)
            subst = unify(e_type, T, subst)
            return Unit(), subst
        else:
            raise ValueError("Malformed term")
    else:
        raise ValueError("Malformed term")

def weak_infer(term: Any) -> str:
    check_malformed(term)
    env = [
        {
            "plus": Func((Int(), Int()), Int()),
            "eq": Func((TVar.fresh(), TVar.fresh()), Bool()),
            "size": Func((Str(),), Int())
        }
    ]
    subst = {}
    typ, subst = infer(term, env, subst)
    typ = apply(subst, typ)
    var_id = 0
    var_map = {}
    def assign_vars(t: Type):
        nonlocal var_id
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_map[t.id] = f"t{var_id + 1}"
                var_id += 1
            return var_map[t.id]
        elif isinstance(t, Func):
            params_str = []
            for p in t.params:
                params_str.append(assign_vars(p))
            ret_str = assign_vars(t.ret)
            return f"({', '.join(params_str)}) -> {ret_str}"
        elif isinstance(t, List):
            return f"List<{assign_vars(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{assign_vars(t.elem)}>"
        else:
            return str(t)
    return assign_vars(typ)

from typing import Dict, List, Tuple, Any, Union
from collections import defaultdict

class Type:
    pass

class TVar(Type):
    def __init__(self, id: int):
        self.id = id

    def __repr__(self):
        return f"TVar({self.id})"

class Int(Type):
    def __repr__(self):
        return "Int"

class Bool(Type):
    def __repr__(self):
        return "Bool"

class Str(Type):
    def __repr__(self):
        return "Str"

class Unit(Type):
    def __repr__(self):
        return "Unit"

class List_(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __repr__(self):
        return f"List({self.elem})"

class Ref(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __repr__(self):
        return f"Ref({self.elem})"

class Func(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

    def __repr__(self):
        return f"Func({self.params}, {self.ret})"

def apply(sub: Dict[int, Type], t: Type) -> Type:
    if isinstance(t, TVar):
        return sub.get(t.id, t)
    elif isinstance(t, List_):
        return List_(apply(sub, t.elem))
    elif isinstance(t, Ref):
        return Ref(apply(sub, t.elem))
    elif isinstance(t, Func):
        return Func(tuple(apply(sub, p) for p in t.params), apply(sub, t.ret))
    else:
        return t

def occurs_check(v: int, t: Type) -> bool:
    if isinstance(t, TVar):
        return t.id == v
    elif isinstance(t, List_):
        return occurs_check(v, t.elem)
    elif isinstance(t, Ref):
        return occurs_check(v, t.elem)
    elif isinstance(t, Func):
        return any(occurs_check(v, p) for p in t.params) or occurs_check(v, t.ret)
    else:
        return False

def unify(t1: Type, t2: Type, sub: Dict[int, Type]) -> Dict[int, Type]:
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if isinstance(t1, TVar):
        if t1.id in sub:
            return unify(sub[t1.id], t2, sub)
        if occurs_check(t1.id, apply(sub, t2)):
            raise ValueError("Infinite type")
        new_sub = dict(sub)
        new_sub[t1.id] = t2
        return new_sub
    elif isinstance(t2, TVar):
        return unify(t2, t1, sub)
    elif isinstance(t1, Int) and isinstance(t2, Int):
        return sub
    elif isinstance(t1, Bool) and isinstance(t2, Bool):
        return sub
    elif isinstance(t1, Str) and isinstance(t2, Str):
        return sub
    elif isinstance(t1, Unit) and isinstance(t2, Unit):
        return sub
    elif isinstance(t1, List_) and isinstance(t2, List_):
        return unify(t1.elem, t2.elem, sub)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        return unify(t1.elem, t2.elem, sub)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            sub = unify(p1, p2, sub)
        return unify(t1.ret, t2.ret, sub)
    else:
        raise ValueError("Type mismatch")

def free_vars(t: Type) -> set:
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, List_):
        return free_vars(t.elem)
    elif isinstance(t, Ref):
        return free_vars(t.elem)
    elif isinstance(t, Func):
        s = set()
        for p in t.params:
            s.update(free_vars(p))
        s.update(free_vars(t.ret))
        return s
    else:
        return set()

def env_free_vars(env: List[Dict[str, Type]]) -> set:
    s = set()
    for d in env:
        for t in d.values():
            s.update(free_vars(t))
    return s

def generalize(t: Type, env: List[Dict[str, Type]]) -> Type:
    s = free_vars(t)
    e = env_free_vars(env)
    quantified = s - e
    if not quantified:
        return t
    return t  # In HM, quantified become universal, but here we just track them in substitution

def check_malformed(term: Any) -> None:
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")
    allowed_tags = {"int", "bool", "str", "unit", "var", "fn", "call", "let", 
                   "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in allowed_tags:
        raise ValueError("Malformed term")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Malformed term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Malformed term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed term")
        names = set()
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("Malformed term")
            if p in names:
                raise ValueError("Malformed term")
            names.add(p)
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed term")
        check_malformed(f)
        for arg in args:
            check_malformed(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        if not isinstance(e1, tuple) or e1[0] != "fn":
            raise ValueError("Malformed term")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed term")
        h, t = term[1], term[2]
        check_malformed(h)
        check_malformed(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Malformed term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not isinstance(tn, str) or hn == tn:
            raise ValueError("Malformed term")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed term")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed term")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed term")
        check_malformed(term[1])
        check_malformed(term[2])

def is_value(term: Any) -> bool:
    if not isinstance(term, tuple):
        return False
    tag = term[0]
    if tag in {"int", "bool", "str", "unit", "var", "nil"}:
        return True
    elif tag == "fn":
        return True
    elif tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    else:
        return False

class Context:
    def __init__(self):
        self.var_counter = 0
        self.env = []
        self.substitution = {}

    def fresh_var(self) -> TVar:
        self.var_counter += 1
        return TVar(self.var_counter)

    def lookup(self, name: str) -> Type:
        for d in reversed(self.env):
            if name in d:
                return d[name]
        raise ValueError("Unbound variable")

    def push_env(self, bindings: List[Tuple[str, Type]]):
        self.env.append(dict(bindings))

    def pop_env(self):
        self.env.pop()

    def unify(self, t1: Type, t2: Type):
        sub = unify(t1, t2, self.substitution)
        self.substitution = sub
        return apply(sub, t1)

def infer(ctx: Context, term: Any) -> Type:
    check_malformed(term)
    tag = term[0]
    if tag == "int":
        return Int()
    elif tag == "bool":
        return Bool()
    elif tag == "str":
        return Str()
    elif tag == "unit":
        return Unit()
    elif tag == "var":
        name = term[1]
        return ctx.lookup(name)
    elif tag == "fn":
        params, body = term[1], term[2]
        param_types = [ctx.fresh_var() for _ in params]
        ctx.push_env([(name, t) for name, t in zip(params, param_types)])
        body_type = infer(ctx, body)
        ctx.pop_env()
        return Func(tuple(param_types), body_type)
    elif tag == "call":
        f, args = term[1], term[2]
        f_type = infer(ctx, f)
        arg_types = [infer(ctx, arg) for arg in args]
        if isinstance(f_type, Func):
            if len(f_type.params) != len(args):
                raise ValueError("Arity mismatch")
            for p, a in zip(f_type.params, arg_types):
                ctx.unify(p, a)
            return apply(ctx.substitution, f_type.ret)
        else:
            raise ValueError("Not a function")
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(ctx, e1)
        if is_value(e1):
            generalized = generalize(e1_type, ctx.env)
        else:
            generalized = e1_type
        ctx.push_env([(name, generalized)])
        e2_type = infer(ctx, e2)
        ctx.pop_env()
        return e2_type
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        if e1[0] != "fn":
            raise ValueError("letrec requires fn")
        f_var = ctx.fresh_var()
        ctx.push_env([(name, f_var)])
        e1_type = infer(ctx, e1)
        ctx.unify(f_var, e1_type)
        generalized = generalize(apply(ctx.substitution, e1_type), ctx.env)
        ctx.pop_env()
        ctx.push_env([(name, generalized)])
        e2_type = infer(ctx, e2)
        ctx.pop_env()
        return e2_type
    elif tag == "nil":
        return List_(ctx.fresh_var())
    elif tag == "cons":
        h, t = term[1], term[2]
        h_type = infer(ctx, h)
        t_type = infer(ctx, t)
        elem = ctx.fresh_var()
        ctx.unify(t_type, List_(elem))
        ctx.unify(h_type, elem)
        return List_(elem)
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = infer(ctx, s)
        a = ctx.fresh_var()
        ctx.unify(s_type, List_(a))
        ctx.push_env([(hn, a), (tn, List_(a))])
        e_nil_type = infer(ctx, e_nil)
        ctx.pop_env()
        ctx.push_env([(hn, a), (tn, List_(a))])
        e_cons_type = infer(ctx, e_cons)
        ctx.pop_env()
        ctx.unify(e_nil_type, e_cons_type)
        return apply(ctx.substitution, e_nil_type)
    elif tag == "ref":
        e = term[1]
        e_type = infer(ctx, e)
        return Ref(e_type)
    elif tag == "get":
        r = term[1]
        r_type = infer(ctx, r)
        t = ctx.fresh_var()
        ctx.unify(r_type, Ref(t))
        return t
    elif tag == "set":
        r, e = term[1], term[2]
        r_type = infer(ctx, r)
        e_type = infer(ctx, e)
        t = ctx.fresh_var()
        ctx.unify(r_type, Ref(t))
        ctx.unify(t, e_type)
        return Unit()
    else:
        raise ValueError("Unknown tag")

def format_type(t: Type) -> str:
    var_names = {}
    var_counter = [0]

    def traverse(tt: Type):
        if isinstance(tt, TVar):
            if tt.id not in var_names:
                var_counter[0] += 1
                var_names[tt.id] = f"t{var_counter[0]}"
            return var_names[tt.id]
        elif isinstance(tt, Int):
            return "Int"
        elif isinstance(tt, Bool):
            return "Bool"
        elif isinstance(tt, Str):
            return "Str"
        elif isinstance(tt, Unit):
            return "Unit"
        elif isinstance(tt, List_):
            return f"List<{traverse(tt.elem)}>"
        elif isinstance(tt, Ref):
            return f"Ref<{traverse(tt.elem)}>"
        elif isinstance(tt, Func):
            if len(tt.params) == 1:
                p = traverse(tt.params[0])
                r = traverse(tt.ret)
                if isinstance(tt.params[0], Func):
                    return f"({p}) -> {r}"
                return f"{p} -> {r}"
            else:
                params = ", ".join(traverse(p) for p in tt.params)
                return f"({params}) -> {traverse(tt.ret)}"
        else:
            raise ValueError("Unknown type")

    return traverse(t)

def weak_infer(term: Any) -> str:
    check_malformed(term)
    ctx = Context()
    # Set up initial environment
    ctx.env = [{
        "Int": Func((Int(), Int()), Int()),
        "eq": Func((ctx.fresh_var(), ctx.fresh_var()), Bool()),
        "size": Func((Str(),), Int())
    }]
    inferred_type = infer(ctx, term)
    final_type = apply(ctx.substitution, inferred_type)
    return format_type(final_type)

from collections import defaultdict

# Global counter for type variables
var_counter = [0]

def var_name(id):
    chars = []
    n = id
    while True:
        n, rem = divmod(n, 26)
        chars.append(chr(ord('a') + rem))
        if n == 0:
            break
        n -= 1
    return ''.join(reversed(chars))

class Type:
    def __init__(self):
        pass

    def __eq__(self, other):
        if not isinstance(other, Type):
            return False
        return self.__dict__ == other.__dict__

class TInt(Type):
    def __repr__(self):
        return "Int"

class TBool(Type):
    def __repr__(self):
        return "Bool"

class TFun(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def __repr__(self):
        return f"({self.a} -> {self.b})"

class TList(Type):
    def __init__(self, a):
        self.a = a
    def __repr__(self):
        return f"(List {self.a})"

class TTuple(Type):
    def __init__(self, components):
        self.components = components
    def __repr__(self):
        if not self.components:
            return "(Tuple)"
        else:
            return f"(Tuple {' '.join(repr(c) for c in self.components)})"

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return var_name(self.id)

def free_vars(t):
    vars = set()
    if isinstance(t, TVar):
        vars.add(t)
    elif isinstance(t, TFun):
        vars.update(free_vars(t.a))
        vars.update(free_vars(t.b))
    elif isinstance(t, TList):
        vars.update(free_vars(t.a))
    elif isinstance(t, TTuple):
        for c in t.components:
            vars.update(free_vars(c))
    return vars

def free_env(env):
    s = set()
    for d in env:
        for t in d.values():
            s.update(free_vars(t))
    return s

def apply(sub, t):
    if isinstance(t, TVar):
        if t in sub:
            return apply(sub, sub[t])
        else:
            return t
    elif isinstance(t, TFun):
        return TFun(apply(sub, t.a), apply(sub, t.b))
    elif isinstance(t, TList):
        return TList(apply(sub, t.a))
    elif isinstance(t, TTuple):
        return TTuple([apply(sub, c) for c in t.components])
    else:
        return t

def unify(t1, t2, sub):
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if t1 == t2:
        return sub
    if isinstance(t1, TVar):
        if t1 in free_vars(t2):
            raise ValueError("Occurs check failed")
        new_sub = dict(sub)
        new_sub[t1] = t2
        return new_sub
    elif isinstance(t2, TVar):
        return unify(t2, t1, sub)
    elif isinstance(t1, TFun) and isinstance(t2, TFun):
        sub = unify(t1.a, t2.a, sub)
        sub = unify(t1.b, t2.b, sub)
        return sub
    elif isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.a, t2.a, sub)
    elif isinstance(t1, TTuple) and isinstance(t2, TTuple):
        if len(t1.components) != len(t2.components):
            raise ValueError("Tuple length mismatch")
        for a, b in zip(t1.components, t2.components):
            sub = unify(a, b, sub)
        return sub
    elif isinstance(t1, TInt) and isinstance(t2, TInt):
        return sub
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return sub
    else:
        raise ValueError("Type mismatch")

def get_fresh_var():
    global var_counter
    var_counter[0] += 1
    return TVar(var_counter[0] - 1)

def initial_env():
    a = get_fresh_var()
    env = []
    env.append({'add': TFun(TInt(), TFun(TInt(), TInt()))})
    env.append({'eq': TFun(a, TFun(a, TBool()))})
    env.append({'nil': TList(a)})
    env.append({'cons': TFun(a, TFun(TList(a), TList(a)))})
    env.append({'head': TFun(TList(a), a)})
    env.append({'tail': TFun(TList(a), TList(a))})
    env.append({'isnil': TFun(TList(a), TBool())})
    return env

def validate_term(term):
    if isinstance(term, int):
        if isinstance(term, bool):
            raise ValueError("Boolean as integer")
        return
    elif term is True or term is False:
        return
    elif isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        return
    elif isinstance(term, tuple):
        if not term:
            raise ValueError("Empty tuple")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Invalid tag")
        if tag == "lam":
            if len(term) != 3:
                raise ValueError("Invalid lambda structure")
            x, body = term[1], term[2]
            validate_term(x)
            validate_term(body)
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Invalid app structure")
            validate_term(term[1])
            validate_term(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Invalid if structure")
            validate_term(term[1])
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("Invalid let structure")
            x = term[1]
            if not isinstance(x, str) or not x:
                raise ValueError("Invalid variable in let")
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("Invalid letrec structure")
            group = term[1]
            body = term[2]
            if not isinstance(group, tuple) or not group:
                raise ValueError("Invalid group in letrec")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("Invalid pair in letrec group")
                name, expr = pair
                if not isinstance(name, str) or not name:
                    raise ValueError("Invalid name in letrec")
                if name in names:
                    raise ValueError("Duplicate name in letrec")
                names.add(name)
                validate_term(expr)
            validate_term(body)
        elif tag == "tuple":
            if len(term) < 1:
                raise ValueError("Invalid tuple structure")
            n = len(term) - 1
            if n == 1:
                raise ValueError("Tuple of length 1")
            for e in term[1:]:
                validate_term(e)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("Invalid proj structure")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Invalid i in proj")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Invalid n in proj")
            if n < 2 or i < 0 or i >= n:
                raise ValueError("Invalid proj indices")
            validate_term(e)
        else:
            raise ValueError("Unknown tag")
    else:
        raise ValueError("Malformed term")

def infer(term, env, sub):
    if isinstance(term, int):
        return TInt()
    elif term is True or term is False:
        return TBool()
    elif isinstance(term, str):
        for d in reversed(env):
            if term in d:
                return apply(sub, d[term])
        raise ValueError(f"Unbound variable {term}")
    elif isinstance(term, tuple):
        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            x_t = get_fresh_var()
            new_env = [dict(env[0])] + env
            new_env[0][x] = x_t
            body_t = infer(body, new_env, sub)
            return TFun(x_t, body_t)
        elif tag == "app":
            f, a = term[1], term[2]
            f_t = infer(f, env, sub)
            a_t = infer(a, env, sub)
            r_t = get_fresh_var()
            sub = unify(f_t, TFun(a_t, r_t), sub)
            return apply(sub, r_t)
        elif tag == "if":
            c, t, e = term[1], term[2], term[3]
            c_t = infer(c, env, sub)
            sub = unify(c_t, TBool(), sub)
            t_t = infer(t, env, sub)
            e_t = infer(e, env, sub)
            sub = unify(t_t, e_t, sub)
            return apply(sub, t_t)
        elif tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            e1_t = infer(e1, env, sub)
            e1_t = apply(sub, e1_t)
            fv = free_vars(e1_t) - free_env(env)
            gen_t = e1_t
            for v in fv:
                new_v = get_fresh_var()
                gen_t = gen_t.replace(v, new_v)
            new_env = [dict(env[0])] + env
            new_env[0][x] = gen_t
            return infer(e2, new_env, sub)
        elif tag == "letrec":
            group, body = term[1], term[2]
            names = []
            exprs = []
            for pair in group:
                name, expr = pair
                names.append(name)
                exprs.append(expr)
            tvs = [get_fresh_var() for _ in names]
            new_env = [dict(env[0])] + env
            for name, tv in zip(names, tvs):
                new_env[0][name] = tv
            inferred = []
            for expr in exprs:
                inferred.append(infer(expr, new_env, sub))
            for name, tv, inf_t in zip(names, tvs, inferred):
                sub = unify(tv, inf_t, sub)
            for name, tv, inf_t in zip(names, tvs, inferred):
                inf_t = apply(sub, inf_t)
                fv = free_vars(inf_t) - free_env(env)
                gen_t = inf_t
                for v in fv:
                    new_v = get_fresh_var()
                    gen_t = gen_t.replace(v, new_v)
                new_env[0][name] = gen_t
            return infer(body, new_env, sub)
        elif tag == "tuple":
            components = term[1:]
            ts = []
            for e in components:
                ts.append(infer(e, env, sub))
            return TTuple(ts)
        elif tag == "proj":
            i, n, e = term[1], term[2], term[3]
            e_t = infer(e, env, sub)
            e_t = apply(sub, e_t)
            if isinstance(e_t, TTuple):
                if len(e_t.components) != n:
                    raise ValueError("Tuple length mismatch")
                return e_t.components[i]
            else:
                raise ValueError("Projection on non-tuple")
    else:
        raise ValueError("Malformed term")

def group_type(term):
    validate_term(term)
    env = initial_env()
    sub = {}
    t = infer(term, env, sub)
    t = apply(sub, t)
    # Collect all TVars in the type, sorted by id
    vars = []
    seen = set()
    def collect(t):
        if isinstance(t, TVar):
            if t not in seen:
                seen.add(t)
                vars.append(t)
        elif isinstance(t, TFun):
            collect(t.a)
            collect(t.b)
        elif isinstance(t, TList):
            collect(t.a)
        elif isinstance(t, TTuple):
            for c in t.components:
                collect(c)
    collect(t)
    # Create a substitution to replace TVars with their names
    name_map = {}
    for v in vars:
        name_map[v] = var_name(v.id)
    def format_type(t):
        if isinstance(t, TVar):
            return name_map[t]
        elif isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        elif isinstance(t, TFun):
            return f"({format_type(t.a)} -> {format_type(t.b)})"
        elif isinstance(t, TList):
            return f"(List {format_type(t.a)})"
        elif isinstance(t, TTuple):
            if not t.components:
                return "(Tuple)"
            else:
                return f"(Tuple {' '.join(format_type(c) for c in t.components)})"
        else:
            raise ValueError("Unknown type")
    return format_type(t)

class TVar:
    count = 0

    def __init__(self):
        self.id = TVar.count
        TVar.count += 1

    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id

    def __hash__(self):
        return hash(self.id)

    def __repr__(self):
        return f"TVar({self.id})"

class TInt: pass
class TBool: pass
class TFun:
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __repr__(self):
        return f"TFun({self.arg}, {self.res})"

class TList:
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"TList({self.elem})"

class TTuple:
    def __init__(self, comps):
        self.comps = comps
    def __repr__(self):
        return f"TTuple({self.comps})"

def free_vars(t, subst):
    if isinstance(t, TVar):
        if t in subst:
            return free_vars(subst[t], subst)
        return {t}
    elif isinstance(t, TFun):
        return free_vars(t.arg, subst) | free_vars(t.res, subst)
    elif isinstance(t, TList):
        return free_vars(t.elem, subst)
    elif isinstance(t, TTuple):
        s = set()
        for c in t.comps:
            s |= free_vars(c, subst)
        return s
    else:
        return set()

def apply(subst, t):
    if isinstance(t, TVar):
        if t in subst:
            return apply(subst, subst[t])
        return t
    elif isinstance(t, TFun):
        return TFun(apply(subst, t.arg), apply(subst, t.res))
    elif isinstance(t, TList):
        return TList(apply(subst, t.elem))
    elif isinstance(t, TTuple):
        return TTuple([apply(subst, c) for c in t.comps])
    else:
        return t

def occurs(v, t, subst):
    t = apply(subst, t)
    if t is v:
        return True
    if isinstance(t, TVar):
        return t == v
    elif isinstance(t, TFun):
        return occurs(v, t.arg, subst) or occurs(v, t.res, subst)
    elif isinstance(t, TList):
        return occurs(v, t.elem, subst)
    elif isinstance(t, TTuple):
        return any(occurs(v, c, subst) for c in t.comps)
    return False

def unify(t1, t2, subst):
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if isinstance(t1, TVar):
        if t1 in subst:
            return unify(subst[t1], t2, subst)
        if occurs(t1, t2, subst):
            raise ValueError("Infinite type")
        subst[t1] = t2
        return subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif isinstance(t1, TFun) and isinstance(t2, TFun):
        subst = unify(t1.arg, t2.arg, subst)
        return unify(t1.res, t2.res, subst)
    elif isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, TTuple) and isinstance(t2, TTuple):
        if len(t1.comps) != len(t2.comps):
            raise ValueError("Tuple length mismatch")
        for a, b in zip(t1.comps, t2.comps):
            subst = unify(a, b, subst)
        return subst
    elif t1 == t2:
        return subst
    else:
        raise ValueError("Type mismatch")

def free_env(env):
    s = set()
    for d in env:
        for t in d.values():
            s |= free_vars(t, {})
    return s

def generalize(t, env):
    fv = free_vars(t, {}) - free_env(env)
    subst = {}
    for v in fv:
        subst[v] = TVar()
    return apply(subst, t)

def name_type(var_counter):
    def name(v):
        n = v.id
        if n < 26:
            return chr(ord('a') + n)
        s = []
        while n >= 26:
            s.append(chr(ord('a') + n % 26))
            n = n // 26 - 1
        s.append(chr(ord('a') + n))
        return ''.join(reversed(s))
    return name

def infer(term, env, subst):
    if isinstance(term, int) and not isinstance(term, bool):
        return TInt()
    elif term is True or term is False:
        return TBool()
    elif isinstance(term, str):
        for d in reversed(env):
            if term in d:
                return d[term]
        raise ValueError(f"Unbound variable {term}")
    elif isinstance(term, tuple):
        if len(term) == 0:
            raise ValueError("Empty tuple")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Invalid tag")
        if tag == "lam":
            if len(term) != 3:
                raise ValueError("Invalid lam")
            x, body = term[1], term[2]
            if not isinstance(x, str) or len(x) == 0:
                raise ValueError("Invalid parameter")
            x_t = TVar()
            new_env = [dict(env[0])] + env
            new_env[0][x] = x_t
            body_t = infer(body, new_env, subst)
            return TFun(x_t, body_t)
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Invalid app")
            f, a = term[1], term[2]
            f_t = infer(f, env, subst)
            a_t = infer(a, env, subst)
            res_t = TVar()
            subst = unify(f_t, TFun(a_t, res_t), subst)
            return apply(subst, res_t)
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Invalid if")
            c, t, e = term[1], term[2], term[3]
            c_t = infer(c, env, subst)
            subst = unify(c_t, TBool(), subst)
            t_t = infer(t, env, subst)
            e_t = infer(e, env, subst)
            subst = unify(t_t, e_t, subst)
            return apply(subst, t_t)
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("Invalid let")
            x, e1, e2 = term[1], term[2], term[3]
            if not isinstance(x, str) or len(x) == 0:
                raise ValueError("Invalid variable name")
            e1_t = infer(e1, env, subst)
            gen_t = generalize(e1_t, env)
            new_env = [dict(env[0])] + env
            new_env[0][x] = gen_t
            return infer(e2, new_env, subst)
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("Invalid letrec")
            group, body = term[1], term[2]
            if not isinstance(group, tuple) or len(group) == 0:
                raise ValueError("Empty group")
            names = []
            tvars = []
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2:
                    raise ValueError("Invalid group item")
                n, e = item
                if not isinstance(n, str) or len(n) == 0:
                    raise ValueError("Invalid name")
                names.append(n)
                tvars.append(TVar())
            new_env = [dict(env[0])] + env
            for n, tv in zip(names, tvars):
                new_env[0][n] = tv
            for (n, e), tv in zip(group, tvars):
                e_t = infer(e, new_env, subst)
                subst = unify(tv, e_t, subst)
            gen_types = []
            for n, tv in zip(names, tvars):
                t = apply(subst, tv)
                gen_t = generalize(t, env)
                gen_types.append((n, gen_t))
            final_env = [dict(env[0])] + env
            for n, t in gen_types:
                final_env[0][n] = t
            return infer(body, final_env, subst)
        elif tag == "tuple":
            if len(term) < 2:
                raise ValueError("Tuple must have at least 2 elements")
            comps = [infer(e, env, subst) for e in term[1:]]
            return TTuple(comps)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("Invalid proj")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Invalid index")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Invalid n")
            if n < 2:
                raise ValueError("n must be >=2")
            if not (0 <= i < n):
                raise ValueError("Index out of range")
            e_t = infer(e, env, subst)
            e_t = apply(subst, e_t)
            if not isinstance(e_t, TTuple):
                raise ValueError("Not a tuple")
            if len(e_t.comps) != n:
                raise ValueError("Tuple length mismatch")
            return e_t.comps[i]
        else:
            raise ValueError(f"Unknown tag: {tag}")
    else:
        raise ValueError("Malformed term")

def validate_term(term):
    if isinstance(term, int) and isinstance(term, bool):
        raise ValueError("Bool is not an int")
    elif term is True or term is False:
        return
    elif isinstance(term, str):
        if len(term) == 0:
            raise ValueError("Empty variable name")
        return
    elif isinstance(term, tuple):
        if len(term) == 0:
            raise ValueError("Empty tuple")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Invalid tag")
        valid_tags = ["lam", "app", "if", "let", "letrec", "tuple", "proj"]
        if tag not in valid_tags:
            raise ValueError(f"Unknown tag {tag}")
        if tag == "lam":
            if len(term) != 3:
                raise ValueError("lam requires 3 elements")
            x, body = term[1], term[2]
            if not isinstance(x, str) or len(x) == 0:
                raise ValueError("Invalid parameter name")
            validate_term(body)
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("app requires 3 elements")
            validate_term(term[1])
            validate_term(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("if requires 4 elements")
            validate_term(term[1])
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("let requires 4 elements")
            x = term[1]
            if not isinstance(x, str) or len(x) == 0:
                raise ValueError("Invalid variable name")
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("letrec requires 3 elements")
            group = term[1]
            if not isinstance(group, tuple) or len(group) == 0:
                raise ValueError("letrec group must be non-empty tuple")
            names = set()
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2:
                    raise ValueError("letrec group items must be (name, expr)")
                n, e = item
                if not isinstance(n, str) or len(n) == 0:
                    raise ValueError("Invalid name in letrec")
                if n in names:
                    raise ValueError("Duplicate name in letrec group")
                names.add(n)
                validate_term(e)
            validate_term(term[2])
        elif tag == "tuple":
            if len(term) < 2:
                raise ValueError("tuple must have at least 2 elements")
            for e in term[1:]:
                validate_term(e)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("proj requires 4 elements")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("proj index must be int")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("proj n must be int")
            if n < 2:
                raise ValueError("proj n must be >=2")
            if not (0 <= i < n):
                raise ValueError("proj index out of range")
            validate_term(e)
        else:
            raise ValueError(f"Unknown tag {tag}")
    else:
        raise ValueError("Malformed term")

def group_type(term):
    TVar.count = 0
    validate_term(term)
    a1 = TVar()
    a2 = TVar()
    a3 = TVar()
    a4 = TVar()
    a5 = TVar()
    a6 = TVar()
    a7 = TVar()
    initial_env = [
        {"add": TFun(TInt, TFun(TInt, TInt))},
        {"eq": TFun(a1, TFun(a1, TBool))},
        {"nil": TList(a2)},
        {"cons": TFun(a3, TFun(TList(a3), TList(a3)))},
        {"head": TFun(TList(a4), a4)},
        {"tail": TFun(TList(a5), TList(a5))},
        {"isnil": TFun(TList(a6), TBool)}
    ]
    subst = {}
    try:
        t = infer(term, initial_env, subst)
    except ValueError as e:
        raise ValueError(str(e))
    t = apply(subst, t)
    vars = list(free_vars(t, {}))
    if not vars:
        return str(t)
    name_map = {}
    for v in vars:
        name_map[v.id] = v
    sorted_vars = sorted(name_map.values(), key=lambda x: x.id)
    var_names = []
    idx = 0
    def get_name(i):
        nonlocal idx
        while True:
            if i < 26:
                name = chr(ord('a') + i)
            else:
                s = []
                n = i
                while n >= 26:
                    s.append(chr(ord('a') + n % 26))
                    n = n // 26 - 1
                s.append(chr(ord('a') + n))
                name = ''.join(reversed(s))
            return name
    name_dict = {}
    for v in sorted_vars:
        name = get_name(idx)
        name_dict[v] = name
        idx += 1
    def var_to_str(v):
        if isinstance(v, TVar):
            return name_dict.get(v, 'a')
        elif isinstance(v, TInt):
            return 'Int'
        elif isinstance(v, TBool):
            return 'Bool'
        elif isinstance(v, TFun):
            return f'(-> {var_to_str(v.arg)} {var_to_str(v.res)})'
        elif isinstance(v, TList):
            return f'(List {var_to_str(v.elem)})'
        elif isinstance(v, TTuple):
            if not v.comps:
                return '(Tuple)'
            else:
                return f'(Tuple {" ".join(var_to_str(c) for c in v.comps)})'
        else:
            raise ValueError("Unknown type")
    return var_to_str(t)

from collections import defaultdict

class Type:
    pass

class TInt(Type):
    def __repr__(self):
        return "Int"

class TBool(Type):
    def __repr__(self):
        return "Bool"

class TFun(Type):
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __repr__(self):
        return f"({self.arg} -> {self.res})"

class TList(Type):
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"(List {self.elem})"

class TTuple(Type):
    def __init__(self, components):
        self.components = components
    def __repr__(self):
        return f"(Tuple {' '.join(map(repr, self.components))})"

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return var_name(self.id)

var_counter = 0

def var_name(var_id):
    n = var_id
    chars = []
    while True:
        n, rem = divmod(n, 26)
        chars.append(chr(ord('a') + rem))
        if n == 0:
            break
        n -= 1
    return ''.join(reversed(chars))

def fresh_var():
    global var_counter
    v = TVar(var_counter)
    var_counter += 1
    return v

def free_vars(type):
    if isinstance(type, TVar):
        return {type}
    elif isinstance(type, TFun):
        return free_vars(type.arg) | free_vars(type.res)
    elif isinstance(type, TList):
        return free_vars(type.elem)
    elif isinstance(type, TTuple):
        return set().union(*[free_vars(t) for t in type.components])
    else:
        return set()

def apply(subst, typ):
    if isinstance(typ, TVar):
        if typ in subst:
            return apply(subst, subst[typ])
        else:
            return typ
    elif isinstance(typ, TFun):
        return TFun(apply(subst, typ.arg), apply(subst, typ.res))
