    def __init__(self, components):
        self.components = components

def group_type(term):
    # Validate term structure
    def validate(term):
        if isinstance(term, bool):
            return
        if isinstance(term, int):
            return
        if isinstance(term, str):
            if not term:
                raise ValueError("Empty string variable")
            return
        if not isinstance(term, tuple):
            raise ValueError("Term is not a tuple")
        if not term:
            raise ValueError("Empty term")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Tag is not a string")
        if tag == "lam":
            if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Invalid lambda term")
            validate(term[2])
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Invalid application term")
            validate(term[1])
            validate(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Invalid if term")
            validate(term[1])
            validate(term[2])
            validate(term[3])
        elif tag == "let":
            if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Invalid let term")
            validate(term[2])
            validate(term[3])
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("Invalid letrec term")
            group = term[1]
            if not isinstance(group, tuple) or not group:
                raise ValueError("Invalid letrec group")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("Invalid letrec pair")
                name, expr = pair
                if not isinstance(name, str) or not name:
                    raise ValueError("Invalid letrec name")
                if name in names:
                    raise ValueError("Duplicate name in letrec")
                names.add(name)
                validate(expr)
            validate(term[2])
        elif tag == "tuple":
            if len(term) < 1:
                raise ValueError("Invalid tuple term")
            if len(term) - 1 == 1:
                raise ValueError("Tuple with one element")
            for e in term[1:]:
                validate(e)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("Invalid projection term")
            i, n = term[1], term[2]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Invalid i in projection")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Invalid n in projection")
            if n < 2 or i < 0 or i >= n:
                raise ValueError("Invalid indices in projection")
            validate(term[3])
        else:
            raise ValueError(f"Unknown tag {tag}")

    validate(term)

    # Initialize environment
    initial_env = [{}]
    tv_counter = [0]

    def fresh_tvar():
        tv = TVar(tv_counter[0])
        tv_counter[0] += 1
        return tv

    eq_a = fresh_tvar()
    initial_env[0]['eq'] = TFun(eq_a, TFun(eq_a, TBool))

    nil_a = fresh_tvar()
    initial_env[0]['nil'] = TList(nil_a)

    cons_a = fresh_tvar()
    initial_env[0]['cons'] = TFun(cons_a, TFun(TList(cons_a), TList(cons_a)))

    head_a = fresh_tvar()
    initial_env[0]['head'] = TFun(TList(head_a), head_a)

    tail_a = fresh_tvar()
    initial_env[0]['tail'] = TFun(TList(tail_a), TList(tail_a))

    isnil_a = fresh_tvar()
    initial_env[0]['isnil'] = TFun(TList(isnil_a), TBool)

    initial_env[0]['add'] = TFun(TInt, TFun(TInt, TInt))

