        queue = deque()
        queue.append((t1, t2))
        while queue:
            a, b = queue.popleft()
            a = apply(subst, a)
            b = apply(subst, b)
            if a == b:
                continue
            if isinstance(a, TVar):
                if a in subst:
                    queue.append((subst[a], b))
