            names = []
            exprs = []
            for name, expr in group:
                names.append(name)
                exprs.append(expr)
            # Create TVar for each name
            tvars = [fresh_tvar() for _ in names]
            # Extend environment with TVar for each name
            new_env = [dict(env[0])]
            for name, tv in zip(names, tvars):
                new_env[0][name] = tv
            # Infer each expression
            inferred = []
            for expr, tv in zip(exprs, tvars):
                inferred_t = infer(expr, new_env, subst)
                inferred.append(inferred_t)
            # Unify each TVar with inferred type
            for tv, inf_t in zip(tvars, inferred):
                subst = unify(tv, inf_t, subst)
            # Now generalize each inferred type
            generalized = []
            for i in range(len(names)):
                t = apply(subst, tvars[i])
                gen_t = generalize(t, env)
                generalized.append(gen_t)
            # Update environment with generalized types
            final_env = [dict(env[0])]
            for name, g_t in zip(names, generalized):
                final_env[0][name] = g_t
            return infer(body, final_env, subst)
        elif tag == "tuple":
            comps = term[1:]
            ts = [infer(e, env, subst) for e in comps]
            return TTuple(ts)
        elif tag == "proj":
            i, n, e = term[1], term[2], term[3]
            t = infer(e, env, subst)
            t = apply(subst, t)
            if not isinstance(t, TTuple):
                raise ValueError("Projection of non-tuple")
            if len(t.components) != n:
                raise ValueError("Tuple length mismatch")
            return t.components[i]
        else:
            raise ValueError(f"Unknown tag {tag}")

    subst = {}
    try:
        result_type = infer(term, initial_env, subst)
    except ValueError as e:
        raise e

    # Apply substitution to the result type
    result_type = apply(subst, result_type)

    # Collect all TVar in the result type
    vars = []
    seen = set()
    def collect_vars(t):
        nonlocal seen
        if isinstance(t, TVar):
            if t not in seen:
                seen.add(t)
                vars.append(t)
        elif isinstance(t, TFun):
            collect_vars(t.a)
            collect_vars(t.b)
        elif isinstance(t, TList):
            collect_vars(t.a)
        elif isinstance(t, TTuple):
            for c in t.components:
                collect_vars(c)
    collect_vars(result_type)

    # Sort variables by id
    var_list = sorted(vars, key=lambda v: v.id)

    # Map each TVar to its name
    var_to_name = {}
    def name_from_id(id):
        s = []
        while True:
            c = id % 26
            s.append(chr(ord('a') + c))
            id = id // 26 - 1
            if id < 0:
                break
        return ''.join(reversed(s))

    for var in var_list:
        var_to_name[var] = name_from_id(var.id)

    # Convert type to string
    def type_to_str(t):
        if isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        elif isinstance(t, TVar):
            return var_to_name[t]
        elif isinstance(t, TFun):
            return f"(-> {type_to_str(t.a)} {type_to_str(t.b)})"
        elif isinstance(t, TList):
            return f"(List {type_to_str(t.a)})"
        elif isinstance(t, TTuple):
            if not t.components:
                return "(Tuple)"
            else:
                return f"(Tuple {' '.join(type_to_str(c) for c in t.components)})"
        else:
            return str(t)

    return type_to_str(result_type)

from collections import deque

class TVar:
    def __init__(self, id):
        self.id = id

    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id

    def __hash__(self):
        return hash(self.id)

    def __repr__(self):
        return f"TVar({self.id})"

class Type:
    pass

class TInt(Type):
    pass

class TBool(Type):
    pass

class TFun(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b

class TList(Type):
    def __init__(self, a):
        self.a = a

class TTuple(Type):
    def __init__(self, components):
        self.components = components

def group_type(term):
    # Validate term structure
    def validate(term):
        if isinstance(term, bool):
            return
        if isinstance(term, int):
            return
        if isinstance(term, str):
            if not term:
                raise ValueError("Empty string variable")
            return
        if not isinstance(term, tuple):
            raise ValueError("Term is not a tuple")
        if not term:
            raise ValueError("Empty term")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Tag is not a string")
        if tag == "lam":
            if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Invalid lambda term")
            validate(term[2])
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Invalid application term")
            validate(term[1])
            validate(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Invalid if term")
            validate(term[1])
            validate(term[2])
            validate(term[3])
        elif tag == "let":
            if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Invalid let term")
            validate(term[2])
            validate(term[3])
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("Invalid letrec term")
            group = term[1]
            if not isinstance(group, tuple) or not group:
                raise ValueError("Invalid letrec group")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("Invalid letrec pair")
                name, expr = pair
                if not isinstance(name, str) or not name:
                    raise ValueError("Invalid letrec name")
                if name in names:
                    raise ValueError("Duplicate name in letrec")
                names.add(name)
                validate(expr)
            validate(term[2])
        elif tag == "tuple":
            if len(term) < 1:
                raise ValueError("Invalid tuple term")
            if len(term) - 1 == 1:
                raise ValueError("Tuple with one element")
            for e in term[1:]:
                validate(e)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("Invalid projection term")
            i, n = term[1], term[2]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Invalid i in projection")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Invalid n in projection")
            if n < 2 or i < 0 or i >= n:
                raise ValueError("Invalid indices in projection")
            validate(term[3])
        else:
            raise ValueError(f"Unknown tag {tag}")

    validate(term)

    # Initialize environment
    initial_env = [{}]
    tv_counter = [0]

    def fresh_tvar():
        tv = TVar(tv_counter[0])
        tv_counter[0] += 1
        return tv

    eq_a = fresh_tvar()
    initial_env[0]['eq'] = TFun(eq_a, TFun(eq_a, TBool))

    nil_a = fresh_tvar()
    initial_env[0]['nil'] = TList(nil_a)

    cons_a = fresh_tvar()
    initial_env[0]['cons'] = TFun(cons_a, TFun(TList(cons_a), TList(cons_a)))

    head_a = fresh_tvar()
    initial_env[0]['head'] = TFun(TList(head_a), head_a)

    tail_a = fresh_tvar()
    initial_env[0]['tail'] = TFun(TList(tail_a), TList(tail_a))

    isnil_a = fresh_tvar()
    initial_env[0]['isnil'] = TFun(TList(isnil_a), TBool)

    initial_env[0]['add'] = TFun(TInt, TFun(TInt, TInt))

    # Helper functions
    def free_vars(t):
        if isinstance(t, TVar):
            return {t}
        elif isinstance(t, TFun):
            return free_vars(t.a) | free_vars(t.b)
        elif isinstance(t, TList):
            return free_vars(t.a)
        elif isinstance(t, TTuple):
            s = set()
            for c in t.components:
                s |= free_vars(c)
            return s
        return set()

    def apply(sub, t):
        if isinstance(t, TVar):
            if t in sub:
                return apply(sub, sub[t])
            return t
        elif isinstance(t, TFun):
            return TFun(apply(sub, t.a), apply(sub, t.b))
        elif isinstance(t, TList):
            return TList(apply(sub, t.a))
        elif isinstance(t, TTuple):
            return TTuple([apply(sub, c) for c in t.components])
        return t

    def unify(t1, t2, subst):
        queue = deque()
        queue.append((t1, t2))
        while queue:
            a, b = queue.popleft()
            a = apply(subst, a)
            b = apply(subst, b)
            if a == b:
                continue
            if isinstance(a, TVar):
                if a in subst:
                    queue.append((subst[a], b))
                    continue
                if a in free_vars(b):
                    raise ValueError("Infinite type")
                subst[a] = b
            elif isinstance(b, TVar):
                if b in subst:
                    queue.append((a, subst[b]))
                    continue
                if b in free_vars(a):
                    raise ValueError("Infinite type")
                subst[b] = a
            elif isinstance(a, TFun) and isinstance(b, TFun):
                queue.append((a.a, b.a))
                queue.append((a.b, b.b))
            elif isinstance(a, TList) and isinstance(b, TList):
                queue.append((a.a, b.a))
            elif isinstance(a, TTuple) and isinstance(b, TTuple):
                if len(a.components) != len(b.components):
                    raise ValueError("Tuple length mismatch")
                for ac, bc in zip(a.components, b.components):
                    queue.append((ac, bc))
            else:
                raise ValueError("Type mismatch")
        return subst

    def free_env(env):
        s = set()
        for d in env:
            for t in d.values():
                s |= free_vars(t)
        return s

    def generalize(t, env):
        fvs = free_vars(t) - free_env(env)
        subst = {}
        for var in list(fvs):
            new_tvar = fresh_tvar()
            subst[var] = new_tvar
        return apply(subst, t)

    def infer(term, env, subst):
        if isinstance(term, bool):
            return TBool()
        if isinstance(term, int):
            return TInt()
        if isinstance(term, str):
            for d in reversed(env):
                if term in d:
                    return apply(subst, d[term])
            raise ValueError(f"Unbound variable {term}")
        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            x_t = fresh_tvar()
            new_env = [dict(env[0])]
            new_env[0][x] = x_t
            body_t = infer(body, new_env, subst)
            return TFun(x_t, body_t)
        elif tag == "app":
            f, a = term[1], term[2]
            f_t = infer(f, env, subst)
            a_t = infer(a, env, subst)
            r_t = fresh_tvar()
            subst = unify(f_t, TFun(a_t, r_t), subst)
            return apply(subst, r_t)
        elif tag == "if":
            c, t, e = term[1], term[2], term[3]
            c_t = infer(c, env, subst)
            subst = unify(c_t, TBool(), subst)
            t_t = infer(t, env, subst)
            e_t = infer(e, env, subst)
            subst = unify(t_t, e_t, subst)
            return apply(subst, t_t)
        elif tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            e1_t = infer(e1, env, subst)
            gen_t = generalize(e1_t, env)
            new_env = [dict(env[0])]
            new_env[0][x] = gen_t
            return infer(e2, new_env, subst)
        elif tag == "letrec":
            group, body = term[1], term[2]
            names = []
            exprs = []
            for name, expr in group:
                names.append(name)
                exprs.append(expr)
            # Create TVar for each name
            tvars = [fresh_tvar() for _ in names]
            # Extend environment with TVar for each name
            new_env = [dict(env[0])]
            for name, tv in zip(names, tvars):
                new_env[0][name] = tv
            # Infer each expression
            inferred = []
            for expr, tv in zip(exprs, tvars):
                inferred_t = infer(expr, new_env, subst)
                inferred.append(inferred_t)
            # Unify each TVar with inferred type
            for tv, inf_t in zip(tvars, inferred):
                subst = unify(tv, inf_t, subst)
            # Now generalize each inferred type
            generalized = []
            for i in range(len(names)):
                t = apply(subst, tvars[i])
                gen_t = generalize(t, env)
                generalized.append(gen_t)
            # Update environment with generalized types
            final_env = [dict(env[0])]
            for name, g_t in zip(names, generalized):
                final_env[0][name] = g_t
            return infer(body, final_env, subst)
        elif tag == "tuple":
            comps = term[1:]
            ts = [infer(e, env, subst) for e in comps]
            return TTuple(ts)
        elif tag == "proj":
            i, n, e = term[1], term[2], term[3]
            t = infer(e, env, subst)
            t = apply(subst, t)
            if not isinstance(t, TTuple):
                raise ValueError("Projection of non-tuple")
            if len(t.components) != n:
                raise ValueError("Tuple length mismatch")
            return t.components[i]
        else:
            raise ValueError(f"Unknown tag {tag}")

    subst = {}
    try:
        result_type = infer(term, initial_env, subst)
    except ValueError as e:
        raise e

    # Apply substitution to the result type
    result_type = apply(subst, result_type)

    # Collect all TVar in the result type
    vars = []
    seen = set()
    def collect_vars(t):
        nonlocal seen
        if isinstance(t, TVar):
            if t not in seen:
                seen.add(t)
                vars.append(t)
        elif isinstance(t, TFun):
            collect_vars(t.a)
            collect_vars(t.b)
        elif isinstance(t, TList):
            collect_vars(t.a)
        elif isinstance(t, TTuple):
            for c in t.components:
                collect_vars(c)
    collect_vars(result_type)

    # Sort variables by id
    var_list = sorted(vars, key=lambda v: v.id)

    # Map each TVar to its name
    var_to_name = {}
    def name_from_id(id):
        # Convert id to base-26 name: 0->'a', 1->'b', ..., 25->'z', 26->'aa', etc.
        s = []
        n = id
        while True:
            s.append(chr(ord('a') + n % 26))
            n = n // 26 - 1
            if n < 0:
                break
        return ''.join(reversed(s))

    for var in var_list:
        var_to_name[var] = name_from_id(var.id)

    # Convert type to string
    def type_to_str(t):
        if isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        elif isinstance(t, TVar):
            return var_to_name[t]
        elif isinstance(t, TFun):
            return f"(-> {type_to_str(t.a)} {type_to_str(t.b)})"
        elif isinstance(t, TList):
            return f"(List {type_to_str(t.a)})"
        elif isinstance(t, TTuple):
            if not t.components:
                return "(Tuple)"
            else:
                return f"(Tuple {' '.join(type_to_str(c) for c in t.components)})"
        else:
            return str(t)

    return type_to_str(result_type)

class Type:
    pass

class TInt(Type):
    def __repr__(self):
        return "Int"

class TBool(Type):
    def __repr__(self):
        return "Bool"

class TFun(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def __repr__(self):
        return f"({self.a} -> {self.b})"

class TList(Type):
    def __init__(self, a):
        self.a = a
    def __repr__(self):
        return f"(List {self.a})"

class TTuple(Type):
    def __init__(self, components):
        self.components = components
    def __repr__(self):
        if not self.components:
            return "()"
        else:
            return "(" + " ".join(repr(c) for c in self.components) + ")"

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return name_var(self.id)

var_counter = 0

def name_var(id):
    n = id + 1
    digits = []
    while n > 0:
        remainder = n % 26
        if remainder == 0:
            remainder = 26
            n = (n - remainder) // 26
        else:
            n = n // 26
        digits.append(remainder)
    digits = digits[::-1]
    return ''.join(chr(ord('a') + d - 1) for d in digits)

def free_vars(t):
    if isinstance(t, TVar):
        return {t}
    elif isinstance(t, TFun):
        return free_vars(t.a) | free_vars(t.b)
    elif isinstance(t, TList):
        return free_vars(t.a)
    elif isinstance(t, TTuple):
        s = set()
        for c in t.components:
            s |= free_vars(c)
        return s
    else:
        return set()

def build_initial_env():
    global var_counter
    var_counter = 0
    base = {}
    base['add'] = TFun(TInt, TFun(TInt, TInt))
    a = TVar(var_counter)
    var_counter += 1
    base['eq'] = TFun(a, TFun(a, TBool))
    a_nil = TVar(var_counter)
    var_counter += 1
    base['nil'] = TList(a_nil)
    a_cons = TVar(var_counter)
    var_counter += 1
    base['cons'] = TFun(a_cons, TFun(TList(a_cons), TList(a_cons)))
    a_head = TVar(var_counter)
    var_counter += 1
    base['head'] = TFun(TList(a_head), a_head)
    a_tail = TVar(var_counter)
    var_counter += 1
    base['tail'] = TFun(TList(a_tail), TList(a_tail))
    a_isnil = TVar(var_counter)
    var_counter += 1
    base['isnil'] = TFun(TList(a_isnil), TBool)
    return [base]

def validate_term(term):
    if isinstance(term, int) and not isinstance(term, bool):
        return
    elif isinstance(term, bool):
        return
    elif isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        return
    elif isinstance(term, tuple):
        if not term:
            raise ValueError("Empty tuple is malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Tag must be a string")
        if tag not in ("lam", "app", "if", "let", "letrec", "tuple", "proj"):
            raise ValueError(f"Unknown tag {tag}")
        if tag == "lam":
            if len(term) != 3:
                raise ValueError("lam needs 3 elements")
            x = term[1]
            if not isinstance(x, str) or not x:
                raise ValueError("lam parameter must be non-empty str")
            validate_term(term[2])
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("app needs 3 elements")
            validate_term(term[1])
            validate_term(term[2])
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("if needs 4 elements")
            validate_term(term[1])
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("let needs 4 elements")
            x = term[1]
            if not isinstance(x, str) or not x:
                raise ValueError("let binding must be non-empty str")
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("letrec needs 3 elements")
            group = term[1]
            if not isinstance(group, tuple):
                raise ValueError("letrec group must be a tuple")
            if not group:
                raise ValueError("letrec group must be non-empty")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("letrec group elements must be (name, expr) tuples")
                name, expr = pair
                if not isinstance(name, str) or not name:
                    raise ValueError("letrec name must be non-empty str")
                if name in names:
                    raise ValueError("letrec group has duplicate names")
                names.add(name)
                validate_term(expr)
            validate_term(term[2])
        elif tag == "tuple":
            if len(term) < 2:
                raise ValueError("tuple tag must be followed by components")
            components = term[1:]
            n = len(components)
            if n == 1:
                raise ValueError("tuple of size 1 is invalid")
            for e in components:
                validate_term(e)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("proj needs 4 elements")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("proj i must be int not bool")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("proj n must be int not bool")
            if n < 2:
                raise ValueError("proj n must be >=2")
            if not (0 <= i < n):
                raise ValueError("proj i out of range")
            validate_term(e)
        else:
            raise ValueError("Unknown tag")
    else:
        raise ValueError("Term is malformed")

def apply(sub, t):
    if isinstance(t, TVar):
        if t in sub:
            return apply(sub, sub[t])
        else:
            return t
    elif isinstance(t, TFun):
        return TFun(apply(sub, t.a), apply(sub, t.b))
    elif isinstance(t, TList):
        return TList(apply(sub, t.a))
    elif isinstance(t, TTuple):
        return TTuple([apply(sub, c) for c in t.components])
    else:
        return t

def occurs_check(v, t):
    if isinstance(t, TVar):
        return t == v
    elif isinstance(t, TFun):
        return occurs_check(v, t.a) or occurs_check(v, t.b)
    elif isinstance(t, TList):
        return occurs_check(v, t.a)
    elif isinstance(t, TTuple):
        return any(occurs_check(v, c) for c in t.components)
    else:
        return False

def unify(t1, t2):
    sub = {}
    worklist = [(t1, t2)]
    while worklist:
        a, b = worklist.pop()
        a = apply(sub, a)
        b = apply(sub, b)
        if a == b:
            continue
        if isinstance(a, TVar):
            if occurs_check(a, b):
                raise ValueError("Infinite type")
            sub[a] = b
        elif isinstance(b, TVar):
            if occurs_check(b, a):
                raise ValueError("Infinite type")
            sub[b] = a
        elif isinstance(a, TFun) and isinstance(b, TFun):
            worklist.append((a.a, b.a))
            worklist.append((a.b, b.b))
        elif isinstance(a, TList) and isinstance(b, TList):
            worklist.append((a.a, b.a))
        elif isinstance(a, TTuple) and isinstance(b, TTuple):
            if len(a.components) != len(b.components):
                raise ValueError("Tuple length mismatch")
            for x, y in zip(a.components, b.components):
                worklist.append((x, y))
        else:
            raise ValueError("Type mismatch")
    return sub

def generalize(t, env):
    fvs = free_vars(t) - free_env(env)
    sub = {}
    for v in fvs:
        new_v = TVar(var_counter)
        var_counter += 1
        sub[v] = new_v
    return apply(sub, t)

def free_env(env):
    s = set()
    for d in env:
        for t in d.values():
            s |= free_vars(t)
    return s

def infer(term, env):
    if isinstance(term, int) and not isinstance(term, bool):
        return TInt()
    elif isinstance(term, bool):
        return TBool()
    elif isinstance(term, str):
        for d in reversed(env):
            if term in d:
                return d[term]
        raise ValueError(f"Unbound variable {term}")
    elif isinstance(term, tuple):
        tag = term[0]
        if tag == "lam":
            x = term[1]
            body = term[2]
            x_t = TVar(var_counter)
            var_counter +=1
            new_env = env.copy()
            new_env[x] = x_t
            body_t = infer(body, new_env)
            return TFun(x_t, body_t)
        elif tag == "app":
            f = term[1]
            a = term[2]
            f_t = infer(f, env)
            a_t = infer(a, env)
            r_t = TVar(var_counter)
            var_counter +=1
            sub = unify(f_t, TFun(a_t, r_t))
            return apply(sub, r_t)
        elif tag == "if":
            c = term[1]
            t1 = term[2]
            t2 = term[3]
            c_t = infer(c, env)
            sub = unify(c_t, TBool())
            t1_t = infer(t1, env)
            t2_t = infer(t2, env)
            sub = unify(apply(sub, t1_t), apply(sub, t2_t))
            return apply(sub, t1_t)
        elif tag == "let":
            x = term[1]
            e1 = term[2]
            e2 = term[3]
            e1_t = infer(e1, env)
            gen_t = generalize(e1_t, env)
            new_env = env.copy()
            new_env[x] = gen_t
            return infer(e2, new_env)
        elif tag == "letrec":
            group = term[1]
            body = term[2]
            names = []
            exprs = []
            for name, expr in group:
                names.append(name)
                exprs.append(expr)
            tvs = []
            for _ in names:
                tv = TVar(var_counter)
                var_counter +=1
                tvs.append(tv)
            env_group = {}
            for name, tv in zip(names, tvs):
                env_group[name] = tv
            env_rec = env.copy()
            env_rec.update(env_group)
            inferred = []
            for expr in exprs:
                inferred.append(infer(expr, env_rec))
            for name, tv, t in zip(names, tvs, inferred):
                sub = unify(tv, t)
                env_group[name] = apply(sub, tv)
            env_final = env.copy()
            for name, t in zip(names, [generalize(apply(sub, tv), env) for tv, sub in zip(tvs, [unify(tv, inferred[i]) for i, (tv, _) in enumerate(zip(tvs, inferred))])])]:
                env_final[name] = t
            return infer(body, env_final)
        elif tag == "tuple":
            components = term[1:]
            ts = [infer(e, env) for e in components]
            return TTuple(ts)
        elif tag == "proj":
            i = term[1]
            n = term[2]
            e = term[3]
            e_t = infer(e, env)
            if not isinstance(e_t, TTuple):
                raise ValueError("Projection on non-tuple")
            if len(e_t.components) != n:
                raise ValueError("Tuple length mismatch")
            return e_t.components[i]
        else:
            raise ValueError(f"Unknown tag {tag}")
    else:
        raise ValueError("Invalid term structure")

def group_type(term):
    validate_term(term)
    global var_counter
    var_counter =0
    env = build_initial_env()
    t = infer(term, env)
    sub = {}
    worklist = [t]
    while worklist:
        current = worklist.pop()
        if isinstance(current, TVar):
            if current in sub:
                current = sub[current]
            else:
                continue
        if isinstance(current, TFun):
            worklist.append(current.a)
            worklist.append(current.b)
        elif isinstance(current, TList):
            worklist.append(current.a)
        elif isinstance(current, TTuple):
            for c in current.components:
                worklist.append(c)
    all_vars = []
    seen = set()
    for v in free_vars(t):
        if v not in seen:
            all_vars.append(v)
            seen.add(v)
    for v in all_vars:
        if v in sub:
            v.t = sub[v]
    sorted_vars = sorted(all_vars, key=lambda x: x.id)
    var_map = {}
    for i, v in enumerate(sorted_vars):
        var_map[v] = TVar(i)
    final_type = apply({v: var_map[v] for v in var_map}, t)
    return repr(final_type)

from typing import Any, Dict, List, Optional, Set, Tuple

class TVar:
    _counter = 0

    def __init__(self):
        self.id = TVar._counter
        TVar._counter += 1

    def __repr__(self):
        return f"TVar({self.id})"

    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id

    def __hash__(self):
        return hash(self.id)

class TInt:
    def __repr__(self):
        return "Int"

class TBool:
    def __repr__(self):
        return "Bool"

class TFun:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __repr__(self):
        return f"(-> {self.left} {self.right})"

class TList:
    def __init__(self, element):
        self.element = element

    def __repr__(self):
        return f"(List {self.element})"

class TTuple:
    def __init__(self, elements):
        self.elements = elements

    def __repr__(self):
        if not self.elements:
            return "(Tuple)"
        return f"(Tuple {' '.join(map(str, self.elements))})"

def free_vars(typ: Any) -> Set[TVar]:
    if isinstance(typ, TVar):
        return {typ}
    elif isinstance(typ, TFun):
        return free_vars(typ.left) | free_vars(typ.right)
    elif isinstance(typ, TList):
        return free_vars(typ.element)
    elif isinstance(typ, TTuple):
        s = set()
        for t in typ.elements:
            s.update(free_vars(t))
        return s
    else:
        return set()

def free_env(env: List[Dict[str, Any]]) -> Set[TVar]:
    s = set()
    for d in env:
        for typ in d.values():
            s.update(free_vars(typ))
    return s

def apply(subst: Dict[TVar, Any], typ: Any) -> Any:
    if isinstance(typ, TVar):
        return subst.get(typ, typ)
    elif isinstance(typ, TFun):
        return TFun(apply(subst, typ.left), apply(subst, typ.right))
    elif isinstance(typ, TList):
        return TList(apply(subst, typ.element))
    elif isinstance(typ, TTuple):
        return TTuple([apply(subst, t) for t in typ.elements])
    else:
        return typ

def occurs(tvar: TVar, typ: Any) -> bool:
    if isinstance(typ, TVar):
        return typ is tvar
    elif isinstance(typ, TFun):
        return occurs(tvar, typ.left) or occurs(tvar, typ.right)
    elif isinstance(typ, TList):
        return occurs(tvar, typ.element)
    elif isinstance(typ, TTuple):
        for t in typ.elements:
            if occurs(tvar, t):
                return True
        return False
    else:
        return False

def unify(t1: Any, t2: Any) -> Dict[TVar, Any]:
    subst = {}

    def _unify(a, b):
        a = apply(subst, a)
        b = apply(subst, b)

        if a == b:
            return
        if isinstance(a, TVar):
            if a in subst:
                _unify(subst[a], b)
                return
            if occurs(a, b):
                raise ValueError("Infinite type")
            subst[a] = b
        elif isinstance(b, TVar):
            if b in subst:
                _unify(a, subst[b])
                return
            if occurs(b, a):
                raise ValueError("Infinite type")
            subst[b] = a
        elif isinstance(a, TFun) and isinstance(b, TFun):
            _unify(a.left, b.left)
            _unify(a.right, b.right)
        elif isinstance(a, TList) and isinstance(b, TList):
            _unify(a.element, b.element)
        elif isinstance(a, TTuple) and isinstance(b, TTuple):
            if len(a.elements) != len(b.elements):
                raise ValueError("Tuple length mismatch")
            for ta, tb in zip(a.elements, b.elements):
                _unify(ta, tb)
        else:
            raise ValueError("Type mismatch")

    _unify(t1, t2)
    return subst

def name_typevar(tvar: TVar) -> str:
    id = tvar.id
    names = []
    while True:
        id += 1
        n = id
        while n > 0:
            names.append(n - 1)
            n = n // 26 - 1
        if names:
            break
    s = []
    for num in names:
        s.append(chr(ord('a') + num))
    return ''.join(reversed(s))

def generalize(typ: Any, env: List[Dict[str, Any]]) -> Any:
    ft = free_vars(typ)
    fe = free_env(env)
    to_quantify = ft - fe
    subst = {}
    for var in to_quantify:
        subst[var] = TVar()
    return apply(subst, typ)

def infer(term: Any, env: List[Dict[str, Any]]) -> Any:
    if isinstance(term, int):
        return TInt()
    elif term is True or term is False:
        return TBool()
    elif isinstance(term, str):
        if not term:
            raise ValueError("Invalid variable name")
        for d in reversed(env):
            if term in d:
                return d[term]
        raise ValueError(f"Unbound variable {term}")
    elif isinstance(term, tuple):
        if not term:
            raise ValueError("Empty tuple")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Invalid tag")
        if tag == "lam":
            if len(term) != 3:
                raise ValueError("Invalid lambda")
            x, body = term[1], term[2]
            if not isinstance(x, str) or not x:
                raise ValueError("Invalid parameter name")
            x_t = TVar()
            new_env = [dict(env[0])] + env
            new_env[0][x] = x_t
            body_t = infer(body, new_env)
            return TFun(x_t, body_t)
        elif tag == "app":
            if len(term) != 3:
                raise ValueError("Invalid application")
            f, a = term[1], term[2]
            f_t = infer(f, env)
            a_t = infer(a, env)
            r_t = TVar()
            subst = unify(f_t, TFun(a_t, r_t))
            return apply(subst, r_t)
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("Invalid if")
            c, t, e = term[1], term[2], term[3]
            c_t = infer(c, env)
            subst = unify(c_t, TBool())
            t_t = infer(t, env)
            e_t = infer(e, env)
            subst = unify(apply(subst, t_t), apply(subst, e_t))
            return apply(subst, t_t)
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("Invalid let")
            x, e1, e2 = term[1], term[2], term[3]
            if not isinstance(x, str) or not x:
                raise ValueError("Invalid variable name")
            t1 = infer(e1, env)
            gen_t1 = generalize(t1, env)
            new_env = [dict(env[0])] + env
            new_env[0][x] = gen_t1
            return infer(e2, new_env)
        elif tag == "letrec":
            if len(term) != 3:
                raise ValueError("Invalid letrec")
            group, body = term[1], term[2]
            if not isinstance(group, tuple) or len(group) == 0:
                raise ValueError("Invalid group")
            names = []
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2:
                    raise ValueError("Invalid group element")
                name, expr = item
                if not isinstance(name, str) or not name:
                    raise ValueError("Invalid variable name")
                if name in names:
                    raise ValueError("Duplicate name in group")
                names.append(name)
            tvars = {name: TVar() for name in names}
            new_env = [dict(env[0])] + env
            for name in names:
                new_env[0][name] = tvars[name]
            for name, expr in group:
                t_expr = infer(expr, new_env)
                subst = unify(tvars[name], t_expr)
                for k in subst:
                    tvars[name] = apply(subst, tvars[name])
            generalized = {}
            for name in names:
                t = tvars[name]
                gen_t = generalize(t, env)
                generalized[name] = gen_t
            new_env = [dict(env[0])] + env
            new_env[0].update(generalized)
            return infer(body, new_env)
        elif tag == "tuple":
            elements = term[1:]
            if len(elements) == 1:
                raise ValueError("Tuple of length 1")
            ts = [infer(e, env) for e in elements]
            return TTuple(ts)
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("Invalid proj")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Invalid index")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Invalid length")
            if n < 2 or i < 0 or i >= n:
                raise ValueError("Invalid proj parameters")
            e_t = infer(e, env)
            subst = unify(e_t, TTuple([TVar() for _ in range(n)]))
            proj_t = apply(subst, e_t)
            if not isinstance(proj_t, TTuple):
                raise ValueError("Projection on non-tuple")
            return proj_t.elements[i]
        else:
            raise ValueError("Unknown tag")
    else:
        raise ValueError("Malformed term")

def group_type(term: Any) -> str:
    TVar._counter = 0
    env = [{}]
    a = TVar()
    env[0]['add'] = TFun(TInt(), TFun(TInt(), TInt()))
    env[0]['eq'] = TFun(a, TFun(a, TBool()))
    env[0]['nil'] = TList(a)
    env[0]['cons'] = TFun(a, TFun(TList(a), TList(a)))
    env[0]['head'] = TFun(TList(a), a)
    env[0]['tail'] = TFun(TList(a), TList(a))
    env[0]['isnil'] = TFun(TList(a), TBool())
    typ = infer(term, env)
    subst = {}
    vars = free_vars(typ)
    for v in vars:
        subst[v] = TVar()
    final_typ = apply(subst, typ)
    var_order = sorted([v for v in vars], key=lambda x: x.id)
    var_map = {}
    for i, v in enumerate(var_order):
        var_map[v] = name_typevar(v)
    def to_str(t):
        if isinstance(t, TVar):
            return var_map.get(t, "?")
        elif isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        elif isinstance(t, TFun):
            return f"(-> {to_str(t.left)} {to_str(t.right)})"
        elif isinstance(t, TList):
            return f"(List {to_str(t.element)})"
        elif isinstance(t, TTuple):
            if not t.elements:
                return "(Tuple)"
            return f"(Tuple {' '.join([to_str(e) for e in t.elements])})"
        else:
            raise ValueError("Unknown type")
    return to_str(final_typ)

