            if op in ('def', 'upd'):
                has_def[x] = True
            if op in ('use', 'upd'):
                if x not in has_def:
                    if x not in uses_exposed:
                        uses_exposed[x] = set()
                    uses_exposed[x].add(u)
        for x in has_def:
            if x not in defs:
                defs[x] = set()
            defs[x].add(u)

    # Compute Dominator Tree using Lengauer-Tarjan algorithm
    parent = [-1] * n
    visited = [False] * n
    post_order = []
    stack = [(entry, False)]
    while stack:
        u, processed = stack.pop()
        if processed:
            post_order.append(u)
            continue
        if visited[u]:
            continue
        visited[u] = True
        stack.append((u, True))
        for v in reversed(succ_reachable[u]):
            if not visited[v]:
                parent[v] = u
                stack.append((v, False))
    post_order.reverse()

    # Compute semi-dominators and immediate dominators
    semi = list(range(n))
    idom = [-1] * n
    ancestor = list(range(n))
    label = list(range(n))

    def find(u):
        if ancestor[u] != u:
            ancestor[u] = find(ancestor[u])
            if semi[label[ancestor[u]]] < semi[label[u]]:
                label[u] = label[ancestor[u]]
        return label[u]

    for u in post_order[1:]:  # Skip entry node
        v = u
        while v != entry and parent[v] != -1:
            w = find(v)
            if semi[w] < semi[u]:
                semi[u] = semi[w]
            v = parent[v]
        if semi[u] == semi[parent[u]]:
            idom[u] = parent[u]
        else:
            idom[u] = find(parent[u])
        # Update ancestor and label
        ancestor[u] = parent[u]
        label[u] = u

    for u in post_order[1:]:
        w = find(u)
        if w != idom[u]:
            idom[u] = idom[w]

    # Build children list for dominator tree
    children = [[] for _ in range(n)]
    for v in range(n):
        if idom[v] != -1 and v != entry:
            children[idom[v]].append(v)

    # Compute entry and exit times for dominance checks
    entry_time = [0] * n
    exit_time = [0] * n
    time = 0

    def dfs(u):
        nonlocal time
        entry_time[u] = time
        time += 1
        for v in children[u]:
            dfs(v)
        exit_time[u] = time
        time += 1

    dfs(entry)

    def strictly_dominates(v, s):
        return (entry_time[v] < entry_time[s] and exit_time[v] > exit_time[s])

    # Compute dominance frontiers
    df = [set() for _ in range(n)]
    for v in range(n):
        for s in succ_reachable[v]:
            if not strictly_dominates(v, s):
                df[v].add(s)
    # Accumulate children's DF
    for v in reversed(post_order):
        for c in children[v]:
            df[v].update(df[c])

    # Prepare the frontier graph for BFS
    frontier_graph = [[] for _ in range(n)]
    for v in range(n):
        for w in df[v]:
            frontier_graph[v].append(w)

    # Process each variable x
    result = []

    all_vars = set()
    if defs:
        all_vars.update(defs.keys())
    if uses_exposed:
        all_vars.update(uses_exposed.keys())
    all_vars.update(params)

    for x in all_vars:
        D = set()
        if x in defs:
            D.update(defs[x])
        if x in params:
            D.add(entry)

        # Compute P(x) via BFS on frontier_graph starting from D
        P = set()
        q = deque()
        for u in D:
            q.append(u)
            P.add(u)
        while q:
            u = q.popleft()
            for v in frontier_graph[u]:
                if v not in P:
                    P.add(v)
                    q.append(v)

        # Compute live_in for x
        live_in = [False] * n
        q = deque()
        for u in uses_exposed.get(x, []):
            live_in[u] = True
            q.append(u)
        while q:
            u = q.popleft()
            for v in pred_reachable[u]:
                if v not in defs.get(x, set()):
                    if not live_in[v]:
                        live_in[v] = True
                        q.append(v)

        # Collect nodes y in P where live_in[y] is True
        phi_nodes = []
        for y in P:
            if live_in[y]:
                phi_nodes.append(y)

        for y in phi_nodes:
            result.append((y, x))

    # Group by node and sort
    from collections import defaultdict
    phi_dict = defaultdict(set)
    for node, name in result:
        phi_dict[node].add(name)

    # Convert to list of tuples and sort
    output = []
    for node in sorted(phi_dict.keys()):
        names = sorted(phi_dict[node])
        output.append((node, names))

    return output

