def format_sigfigs(s: str, sig: int, mode: str) -> str:
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if not isinstance(sig, int) or isinstance(sig, bool) or sig < 1 or sig > 2000:
        raise ValueError("sig must be an integer between 1 and 2000")
    valid_modes = {"nearest_even", "nearest_away", "nearest_zero", "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"}
    if mode not in valid_modes:
        raise ValueError("mode must be one of the valid modes")
    if len(s) > 100000:
        raise ValueError("s is too long")

    # Parse the input string
    sign = 1
    if s and s[0] in '+-':
        if s[0] == '-':
            sign = -1
        s = s[1:]

    # Split into mantissa and exponent parts
    e_pos = -1
    for i, c in enumerate(s):
        if c in 'eE':
            e_pos = i
            break
    if e_pos != -1:
        mantissa_part = s[:e_pos]
        exp_str = s[e_pos+1:]
    else:
        mantissa_part = s
        exp_str = ""

    # Parse exponent
    E = 0
    if exp_str:
        if exp_str[0] in '+-':
            exp_sign = -1 if exp_str[0] == '-' else 1
            exp_digits = exp_str[1:]
        else:
            exp_sign = 1
            exp_digits = exp_str
        if not exp_digits.isdigit() or len(exp_digits) < 1 or len(exp_digits) >10:
            raise ValueError("Invalid exponent")
        E = exp_sign * int(exp_digits)

    # Parse mantissa
    if '.' in mantissa_part:
        dot_pos = mantissa_part.find('.')
        left_part = mantissa_part[:dot_pos]
        right_part = mantissa_part[dot_pos+1:]
    else:
        dot_pos = len(mantissa_part)
        left_part = mantissa_part
        right_part = ''

    # Concatenate all digits into D
    D = list(left_part + right_part)
    if not D:
        raise ValueError("Invalid mantissa")

    # Check for at least one digit
    if not any(c.isdigit() for c in D):
        raise ValueError("Invalid mantissa")

    # Remove leading zeros to find first_nonzero
    first_nonzero = 0
    while first_nonzero < len(D) and D[first_nonzero] == '0':
        first_nonzero +=1

    # Handle all zeros case
    if first_nonzero == len(D):
        return "0e+00" if sig ==1 else "0." + "0"*(sig-1) + "e+00"

    # Compute k: digits before '.'
    k = dot_pos if '.' in mantissa_part else len(left_part)

    # Compute leading_zeros (number of leading zeros in D)
    leading_zeros = first_nonzero

    # Compute exponent of first significant digit
    exp = E + k -1 - leading_zeros

    # Determine cut position
    cut = first_nonzero + sig -1

    # Check if no rounding is needed
    if cut >= len(D):
        # No rounding needed, just format
        digits_needed = sig
        mantissa_str = ''.join(D[first_nonzero:cut+1])
        if len(mantissa_str) < digits_needed:
            mantissa_str += '0' * (digits_needed - len(mantissa_str))
        else:
            mantissa_str = mantissa_str[:digits_needed]
    else:
        # Need to round
        # Analyze dropped digits
        dropped = D[cut+1:]
        # Check if all zeros
        all_zero = all(c == '0' for c in dropped)
        # Check if exactly half (5 followed by zeros)
        is_half = False
        if dropped and dropped[0] == '5':
            is_half = all(c == '0' for c in dropped[1:])
        # Determine if greater than half
        greater_half = False
        if dropped:
            if dropped[0] > '5':
                greater_half = True
            elif dropped[0] == '5':
                if any(c != '0' for c in dropped[1:]):
                    greater_half = True

        # Decide to increment based on mode
        increment = False
        if mode == "toward_zero":
            increment = False
        elif mode == "away_zero":
            increment = not all_zero
        elif mode == "toward_neg":
            increment = not all_zero
        elif mode == "toward_pos":
            increment = not all_zero
        elif mode == "nearest_even":
            if greater_half:
                increment = True
            elif is_half:
                last_digit = D[cut]
                increment = int(last_digit) % 2 != 0
        elif mode == "nearest_away":
            increment = greater_half or is_half
        elif mode == "nearest_zero":
            increment = greater_half
        elif mode == "zero_five":
            last_digit = D[cut]
            if last_digit in ('0', '5') and not all_zero:
                increment = True
            else:
                increment = False

        if increment:
            # Need to carry
            carry = 1
            i = cut
            while i >= 0 and carry:
                new_val = int(D[i]) + carry
                if new_val == 10:
                    D[i] = '0'
                    carry = 1
                else:
                    D[i] = str(new_val)
                    carry = 0
                i -=1
            if carry:
                # Carry out of the first_nonzero position
                D = ['1'] + D
                first_nonzero = 0
                exp +=1
            cut +=1  # since we added a digit

        # Now, take the first sig digits starting from first_nonzero
