        if '.' in base_str:
            parts = base_str.split('.', 1)
            integer_part = parts[0]
            fractional_part = parts[1] if len(parts) > 1 else ''
        else:
            integer_part = base_str
            fractional_part = ''
        digits_str = integer_part + fractional_part
        if not digits_str:
            N_base = 0
        else:
            N_base = int(digits_str)
        fractional_length = len(fractional_part)
        E = exponent_part - fractional_length
        N = sign * N_base
        return N, E

    N_x, E_x = parse_decimal(x_str)
    N_step, E_step = parse_decimal(step_str)

    if N_step <= 0:
        raise ValueError

    # Compute m_step and e_step for the step
    temp = N_step
    count = 0
    while temp % 10 == 0 and temp != 0:
        temp = temp // 10
        count += 1
    m_step = temp
    e_step = E_step + count
    d = max(0, -e_step)

    # Compute shift and scaled integers
    shift = E_x - E_step
    num = N_x * (10 ** max(0, shift))
    den = N_step * (10 ** max(0, -shift))

    q = num // den
    r = num % den

    if r == 0:
        k_target = q
    else:
        if mode == 'floor':
            k_target = q
        elif mode == 'ceil':
            k_target = q + 1
        elif mode == 'outward':
            if N_x >= 0:
                k_target = q + 1
            else:
                k_target = q
        elif mode == 'inward':
            if N_x >= 0:
                k_target = q
            else:
                k_target = q + 1
        elif mode == 'tie_even':
            if 2 * r < den:
                k_target = q
            elif 2 * r > den:
                k_target = q + 1
            else:
                if q % 2 == 0:
                    k_target = q
                else:
                    k_target = q + 1
        elif mode == 'tie_odd':
            if 2 * r < den:
                k_target = q
            elif 2 * r > den:
                k_target = q + 1
            else:
                if q % 2 != 0:
                    k_target = q
                else:
                    k_target = q + 1
        elif mode == 'tie_away':
            if 2 * r < den:
                k_target = q
            elif 2 * r > den:
                k_target = q + 1
            else:
                if N_x >= 0:
                    k_target = q + 1
                else:
                    k_target = q
        elif mode == 'tie_zero':
            if 2 * r < den:
                k_target = q
            elif 2 * r > den:
                k_target = q + 1
            else:
                if abs(q) < abs(q + 1):
                    k_target = q
                else:
                    k_target = q + 1
        else:
            raise ValueError("Invalid mode")

    # Compute S = m_step * 10^{max(e_step,0)}
    exponent = max(e_step, 0)
    S = m_step * (10 ** exponent)

    R = k_target * S

    # Estimate digit count to check size limit
    if R == 0:
        total_length = 1 + d
    else:
        str_R = str(abs(R))
        integer_digits = len(str_R)
        if integer_digits <= d:
            total_length = 1 + d
        else:
            total_length = integer_digits
    if total_length > 3000:
        raise ValueError

    # Format the output
    if R == 0:
        if d == 0:
            return "0"
        else:
            return "0." + "0" * d
    else:
        sign = '-' if R < 0 else ''
        R_abs = abs(R)
        str_R = str(R_abs)
        if d == 0:
            return sign + str_R
        else:
            if len(str_R) <= d:
                integer_part = "0"
                fractional_part = str_R.zfill(d)
            else:
                integer_part = str_R[:-d]
                fractional_part = str_R[-d:]
            integer_part = integer_part.lstrip('0') or '0'
            return f"{sign}{integer_part}.{fractional_part}"

